/* Wissen › Wiederholung, KW 48/2026. */
WDH_woche({"kw": "2026-W48", "von": "2026-11-23", "bis": "2026-11-29", "plan": {"mo": "w48-nack", "mi": "w48-rad"}, "einheiten": [{"id": "w48-nack", "titel": "Nicht-spezifischer Nackenschmerz", "art": "kb", "kb": "WS05", "min": 11, "abschnitte": [{"t": "1. Was ist das eigentlich?", "b": [{"p": ["Nicht-spezifisch heißt: Schmerz im Nacken, oft bis in die Schulter und den Hinterkopf, ohne Hinweis auf Fraktur, [[Myelopathie|myelo]], Radikulopathie, Gefäß-, Tumor- oder Entzündungsursache. Grundlage in Deutschland ist die [[DEGAM-S3-Leitlinie 2025|degam]]."]}, {"l": ["Häufigkeit: 45,7 % der Erwachsenen in Deutschland hatten in den letzten 12 Monaten Nackenschmerz (RKI BURDEN 2020). Weltweit waren es 2020 rund 203 Millionen Betroffene, für 2050 werden etwa 269 Millionen erwartet (GBD 2021).", "Frauen sind häufiger betroffen, am häufigsten zwischen 45 und 74 Jahren.", "Eine gefährliche Ursache steckt bei unter 1 % dahinter. Genau die soll man aber nicht übersehen, siehe Abschnitt 3.", "Ursachen sind meist mehrere zugleich: viel Bildschirmarbeit, wenig Kraft und Ausdauer der Nackenmuskeln, Stress, schlechter Schlaf."]}]}, {"t": "2. Einteilung und Verlauf", "b": [{"tab": [["Akut", "0–3 Wochen (DEGAM). Die JOSPT-Leitlinie zählt alles unter 6 Wochen als akut."], ["Subakut", "4–12 Wochen"], ["Chronisch", "über 12 Wochen"]], "p": ["Die [[JOSPT-Einteilung|jospt]] trennt zusätzlich vier klinische Bilder: mit Mobilitätsdefizit, mit Koordinationsstörung (oft nach Schleudertrauma), mit Kopfschmerz und mit ausstrahlendem Schmerz. Die Gruppe steuert die Behandlung."]}, {"bars": [["Schmerz am Anfang", 64, "von 100 im Mittel zu Beginn"], ["Nach 6,5 Wochen", 35, "deutlicher Rückgang in den ersten Wochen"], ["Nach 12 Monaten", 42, "die Kurve flacht ab, viele behalten leichte Beschwerden"]]}, {"p": ["Die Werte stammen aus der Metaanalyse von Hush 2011. 50–75 % haben 1–5 Jahre später wieder Nackenschmerz. Ungünstig für den Verlauf sind vor allem psychosoziale Faktoren: starke Schmerzen, hohe Beeinträchtigung, Katastrophisieren, Angst. Nach einem Schleudertrauma gelten NRS ab 6, NDI über 30 % und ein Katastrophisierungswert (PCS) ab 20 als Warnwerte."], "merk": "Der Nacken bessert sich in den ersten 6 Wochen meist deutlich, Rückfälle sind aber häufig. Training senkt das Risiko."}]}, {"t": "3. Red Flags zuerst", "b": [{"tab": [["Trauma", "Verdacht auf Fraktur nach Unfall: [[Canadian C-Spine Rule|ccsr]] anwenden, ärztlich"], ["Myelopathie", "Gangunsicherheit, ungeschickte Hände, beidseitige Missempfindungen. [[Cook-Cluster|cook]] nutzen"], ["Gefäße", "Schwindel, Doppelbilder, Sprach- oder Schluckstörung, Fallattacken, Nystagmus, neu einsetzender heftiger Kopf- oder Nackenschmerz ([[IFOMPT-Rahmen|ifompt]]). Sofort ärztlich"], ["Infektion, Entzündung", "Fieber, Nackensteife"], ["Tumor", "Tumoranamnese, Gewichtsverlust, Nachtschmerz"]], "merk": "Vor jeder Behandlung der HWS Gefäß- und Myelopathiezeichen abfragen. Kein einzelner Test schließt eine Dissektion aus, entscheidend ist die Anamnese."}]}, {"t": "4. Befund und Abgrenzung", "b": [{"l": ["Aktive Beweglichkeit von HWS und BWS, dazu Schulterblattkontrolle und Kraft für Nacken und Schulter.", "Bei Kopfschmerz der [[Flexions-Rotations-Test|frt]]: positiv bei unter 32° oder mehr als 10° unter dem Normalwert von etwa 44°.", "Ausdauer der tiefen Halsbeuger: Norm bei Männern etwa 39 s, bei Frauen etwa 29 s, mit großer Streuung (Domenech 2011).", "Bei Armsymptomen: Neurologie, Spurling-Test, ULTT. Dann ist es eher eine zervikale Radikulopathie."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/kopf-ccft.webp", "t": "Kraniozervikaler Flexionstest.", "c": "Hakenlage, Luftkissen unter dem Nacken auf 20 mmHg. Kleines Ja-Nicken, jede Stufe 10 s halten, der SCM soll nicht mitarbeiten. Dieselbe Bewegung ist die Grundübung für die tiefen Halsbeuger."}]}, {"tab": [["Zervikale Radikulopathie", "Armschmerz im Dermatom, Ausfälle. Spurling, Distraktion, ULTT, Neurologie"], ["Zervikale Myelopathie", "Gang unsicher, Hände ungeschickt, beidseits. Cook-Cluster, ärztlich"], ["Schleudertrauma", "Unfallhergang. Anamnese, Canadian C-Spine Rule"], ["Zervikogener Kopfschmerz", "einseitig, durch Nackenbewegung ausgelöst. Flexions-Rotations-Test"], ["Dissektion", "neuer heftiger Schmerz, Hirnnervenzeichen. Sofort ärztlich"], ["Schulter", "Schmerz bei Armbewegung, nicht bei HWS-Bewegung. Schultertests"]]}, {"l": ["Messen im Verlauf: [[NDI|ndi]] (spürbar etwa 7,5 von 50 Punkten), NPRS (1,3–2 Punkte), PSFS (etwa 2 Punkte).", "Bildgebung nur bei Warnzeichen (DEGAM, Grad A). Sonst nach 4–6 Wochen neu einschätzen."], "merk": "Ohne Warnzeichen kein Röntgen und kein MRT. Der Befund steuert die Übungen, nicht das Bild."}, {"p": ["KI-erstellte Lehrbilder nach typischen Lehrbuchfällen, geprüft, keine echten Aufnahmen."]}]}, {"t": "5. Was hilft laut Studienlage?", "b": [{"p": ["Die DEGAM-Leitlinie stellt aktive Behandlung klar vor passive. Körperliche Aktivität und Bewegungstherapie bei chronischem Nackenschmerz bekommen Grad A, Aufklärung und Wärme in Eigenanwendung Grad B. Manuelle Therapie, Weichteiltechniken und Akupunktur sind nur „kann“, und auch das nur zusammen mit aktivierenden Maßnahmen."]}, {"l": ["Krafttraining für Nacken, Schultergürtel und Arme ist gut belegt (Cochrane, Gross 2015).", "Dosis: [[Andersen 2012|andersen]] zeigte bei 447 Büroangestellten, dass 1 Stunde Nacken-Schulter-Training pro Woche über 20 Wochen wirkt, egal ob am Stück oder aufgeteilt. Schon 2 Minuten Theraband täglich an 5 Tagen bringen etwas.", "Übungsform: Kraft, Motorkontrolle, Yoga, Pilates und Tai Chi wirken etwa gleich gut ([[de Zoete 2021|dezoete]]). Eine Übersicht über 25 Reviews kommt zum selben Schluss und findet für Krafttraining allein bei der Beeinträchtigung keinen klaren Effekt ([[Rasmussen-Barr 2023|rasmussen]]).", "Thorakale Manipulation oder HWS-Mobilisation: kurzfristig weniger Schmerz, immer als Ergänzung zu Übungen.", "Vorbeugung: Übungen senken neue Episoden deutlich (OR 0,32, de Campos 2018). Ergonomieprogramme allein tun das nicht.", "Massage: akut nicht. Bei chronischem Nackenschmerz nur hoch dosiert (60 Minuten) und mit Aktivierung (Sherman 2014).", "Zervikogener Kopfschmerz: manuelle Therapie der oberen HWS plus Training der tiefen Halsbeuger mit niedriger Last, etwa 6 Wochen, der Effekt hielt nach 12 Monaten noch (Jull 2002)."]}, {"tab": [["Nicht empfohlen (DEGAM, Grad B)", "Traktion, Elektrotherapie, Laser, Kinesiotape"], ["Ebenfalls nicht empfohlen", "Ultraschall, Halskrause, Fango und Rotlicht als Verordnung, passive Maßnahmen allein"]], "merk": "Welche Übungsform, ist fast egal. Wichtig ist, dass der Patient regelmäßig trainiert, mindestens etwa 1 Stunde pro Woche."}, {"p": ["Ein Widerspruch: Die JOSPT-Leitlinie von 2017 gibt Laser, Traktion und Dry Needling bei chronischem Mobilitätsdefizit Grad B. DEGAM, KNGF und OPTIMa raten davon ab. Für Deutschland gilt die neuere DEGAM-Leitlinie."]}]}, {"t": "6. Was neu ist", "b": [{"l": ["Die JOSPT-Leitlinie zum Nackenschmerz wird überarbeitet, die Neufassung ist noch nicht erschienen. Bis dahin gilt die Revision von 2017.", "[[Peters 2025|peters]] hat 19 internationale Leitlinien verglichen. Alle hochwertigen empfehlen Mobilisation oder Manipulation, mit oder ohne Übungen. Das Screening auf Gefäßrisiken beschreiben aber nur 2 der 19 vollständig. Dafür bleibt der IFOMPT-Rahmen die Grundlage."]}]}, {"t": "7. Für den Praxisalltag", "b": [{"l": ["Im ersten Termin erklären: meist harmlos, den Kopf normal weiter bewegen, keine Halskrause.", "Heimprogramm mit Kraft für Nacken und Schulter planen, zum Beispiel Rudern, Shrugs und Außenrotation, 3 × 10–15. Wer wenig Zeit hat, macht kurze Einheiten.", "Kraniozervikale Flexion, 10 × 10 s halten. Diese Dosierung ist Expertenmeinung.", "Die Übungsform nehmen, die der Patient auch durchhält. Yoga oder Pilates sind eine echte Alternative.", "Am Arbeitsplatz: Bildschirmhöhe, Pausen, Positionswechsel. Keine „richtige“ Haltung erzwingen.", "NDI am Anfang und nach 4–6 Wochen erheben, Ziel mindestens 7,5 Punkte besser.", "Vor Mobilisation oder Manipulation der HWS Gefäßzeichen und Risikofaktoren abfragen und dokumentieren."], "merk": "Fürs Patientengespräch: „Nackenschmerzen sind meist harmlos. Bewegen Sie den Kopf normal weiter. Am besten hilft regelmäßiges Krafttraining, schon kurze Einheiten zählen.“"}]}], "quellen": ["DEGAM S3 Nicht-spezifische Nackenschmerzen, AWMF 053-007, Version 3.0, 2025, gültig bis 17.02.2030", "Blanpied PR et al. Neck Pain: Clinical Practice Guidelines Revision 2017. JOSPT 2017", "Gross A et al. Exercise therapy for mechanical neck disorders. Cochrane 2015", "Andersen CH et al. Br J Sports Med 2012 (Häufigkeit und Dauer des Krafttrainings)", "de Zoete RMJ et al. Br J Sports Med 2021 (Netzwerk-Metaanalyse Übungsformen)", "Rasmussen-Barr E et al. BMC Musculoskelet Disord 2023 (Übersicht über 25 Reviews)", "Peters R et al. Phys Ther 2025 (Leitlinienvergleich Mobilisation und Gefäß-Screening)", "Rushton A et al. IFOMPT International Framework Cervical Spine. JOSPT 2023", "Hush JM et al. 2011 (Prognose); Cook C et al. 2010 (Myelopathie-Cluster); Domenech 2011 (Normwerte tiefe Halsbeuger)", "de Campos TF et al. 2018 (Vorbeugung); Sherman KJ et al. 2014 (Massage); Jull G et al. Spine 2002 (zervikogener Kopfschmerz)", "RKI BURDEN 2020; GBD 2021"], "fragen": [["Ab wann gilt Nackenschmerz laut DEGAM als chronisch?", ["Nach 4 Wochen", "Nach 6 Wochen", "Nach 6 Monaten", "Nach mehr als 12 Wochen"], 3, "DEGAM teilt ein in akut 0–3, subakut 4–12 und chronisch über 12 Wochen. Die JOSPT-Leitlinie nennt alles unter 6 Wochen akut."], ["Welche Maßnahme hat in der DEGAM-Leitlinie den Empfehlungsgrad A?", ["Traktion", "Bewegungstherapie bei chronischem Nackenschmerz", "Massage", "Kinesiotape"], 1, "Körperliche Aktivität und Bewegungstherapie bekommen Grad A. Traktion und Kinesiotape werden nicht empfohlen, Massage nur eingeschränkt."], ["Was zeigte Andersen 2012 zur Aufteilung von 1 Stunde Nacken-Schulter-Training pro Woche?", ["Ob am Stück oder aufgeteilt, machte keinen Unterschied", "Nur am Stück wirkt es", "Viele kurze Einheiten sind schlechter", "Aufgeteilt wirkt es nur bei Männern"], 0, "Ob 1 × 60, 3 × 20 oder 9 × 7 Minuten, der Schmerz sank gleich stark. Wichtig ist die Gesamtdosis."], ["Welche Übungsform ist bei chronischem Nackenschmerz laut den Übersichtsarbeiten am besten?", ["Nur Krafttraining", "Keine ist klar überlegen", "Nur Motorkontrolle der tiefen Halsbeuger", "Nur Yoga"], 1, "de Zoete 2021 und Rasmussen-Barr 2023 finden keine klar überlegene Form. Entscheidend ist, dass regelmäßig trainiert wird."], ["Ab wann gilt der Flexions-Rotations-Test als positiv?", ["Unter 60° Rotation", "Nur bei Schmerz, unabhängig vom Winkel", "Unter 32° oder mehr als 10° unter dem Normalwert", "Über 44° Rotation"], 2, "Normal sind etwa 44° je Seite. Unter 32° oder eine Abweichung über 10° spricht für eine Störung in C1/C2, typisch beim zervikogenen Kopfschmerz."], ["Ab wie vielen positiven Zeichen im Cook-Cluster ist eine Myelopathie sehr wahrscheinlich?", ["Ab 1", "Ab 3", "Ab 2", "Erst bei allen 5"], 1, "Ab 3 von 5 Zeichen ist die Myelopathie sehr wahrscheinlich (LR+ 30,9). Höchstens 1 positives Zeichen macht sie unwahrscheinlich (LR− 0,18)."], ["Welches Zeichen spricht bei Nackenschmerz für eine Gefäßursache?", ["Schmerz beim langen Sitzen", "Verspannter Trapezius", "Schmerz bei Rotation nach links", "Doppelbilder"], 3, "Doppelbilder, Schwindel, Sprach- oder Schluckstörung, Fallattacken, Nystagmus und neuer heftiger Kopf- oder Nackenschmerz sind Gefäßzeichen. Dann sofort ärztlich."], ["Welche Änderung im NDI gilt als spürbar?", ["Etwa 2 von 50 Punkten", "Etwa 20 von 50 Punkten", "Etwa 7,5 von 50 Punkten", "Erst eine Halbierung"], 2, "Je nach Studie liegt die Schwelle bei 5–33 %, typisch sind etwa 7,5 von 50 Punkten oder 15 %."], ["Welcher Muskel ist mit der 7 markiert?", ["M. sternocleidomastoideus", "M. scalenus anterior", "M. longus colli", "M. levator scapulae"], 2, "Der M. longus colli liegt vorne direkt auf den Wirbelkörpern. Er ist einer der tiefen Halsbeuger und wird mit der kraniozervikalen Flexion trainiert.", "fortbildung/bilder/2026-W47/ana-hws-muskeln2.webp"], ["Wie viele haben 1–5 Jahre nach einer Episode wieder Nackenschmerz?", ["Etwa 5–10 %", "Etwa 20 %", "Etwa 50–75 %", "Fast alle"], 2, "Rückfälle sind häufig, 50–75 % haben in 1–5 Jahren erneut Beschwerden. Regelmäßiges Training senkt das Risiko."], ["Was empfiehlt die DEGAM-Leitlinie ausdrücklich nicht?", ["Wärme in Eigenanwendung", "Aufklärung", "Krafttraining", "Kinesiotape"], 3, "Traktion, Elektrotherapie, Laser und Kinesiotape werden mit Grad B nicht empfohlen. Wärme und Aufklärung haben Grad B als Empfehlung."], ["Was hilft beim zervikogenen Kopfschmerz laut Studienlage?", ["Manuelle Therapie der oberen HWS plus Training der tiefen Halsbeuger", "Halskrause für zwei Wochen", "Nur Massage der Schultermuskeln", "Traktion der HWS"], 0, "Jull 2002: Manuelle Therapie plus Training der tiefen Halsbeuger über etwa 6 Wochen, der Effekt hielt nach 12 Monaten."], ["Was senkt laut de Campos 2018 das Risiko einer neuen Nackenschmerz-Episode?", ["Übungen", "Ergonomieprogramme allein", "Ein neues Kopfkissen", "Regelmäßige Massage"], 0, "Übungen senken neue Episoden deutlich (OR 0,32). Ergonomieprogramme allein zeigten keinen Effekt."]], "info": {"myelo": {"t": "Zervikale Myelopathie", "x": ["Druck auf das Rückenmark im Halsbereich, meist durch Verschleiß.", "Typisch: unsicherer Gang, ungeschickte Hände, beidseitige Missempfindungen. Gehört ärztlich abgeklärt."], "q": "Cook 2010"}, "degam": {"t": "DEGAM S3 2025", "x": ["Leitlinie Nicht-spezifische Nackenschmerzen, AWMF 053-007, Version 3.0, gültig bis 17.02.2030.", "Grad A: Aktivität und Bewegungstherapie bei chronischem Nackenschmerz. Grad B: Aufklärung, Wärme. Nicht empfohlen (Grad B): Traktion, Elektrotherapie, Laser, Kinesiotape."], "q": "AWMF 053-007"}, "jospt": {"t": "JOSPT-Einteilung", "x": ["Nackenschmerz mit Mobilitätsdefizit, mit Koordinationsstörung, mit Kopfschmerz, mit ausstrahlendem Schmerz.", "Die Leitlinie (Revision 2017) wird gerade überarbeitet. Bis die Neufassung erscheint, gilt die Fassung von 2017."], "q": "Blanpied 2017"}, "ccsr": {"t": "Canadian C-Spine Rule", "x": ["Entscheidungsregel nach Nackentrauma, ob geröntgt werden muss.", "Sensitivität 1,00 in einer Metaanalyse 2023: Wer nach der Regel kein Bild braucht, hat praktisch keine Fraktur."], "q": "Metaanalyse 2023"}, "cook": {"t": "Cook-Cluster", "x": ["Fünf Zeichen für eine zervikale Myelopathie: Gangabweichung, Hoffmann-Zeichen, inverser Radiusreflex, Babinski, Alter über 45.", "Höchstens 1 positiv: Myelopathie unwahrscheinlich (LR− 0,18). 3 oder mehr: sehr wahrscheinlich (LR+ 30,9)."], "q": "Cook 2010"}, "ifompt": {"t": "IFOMPT-Rahmen", "x": ["Internationaler Rahmen zur Untersuchung der HWS auf Gefäßursachen vor manueller Therapie (2020, JOSPT 2023).", "Kein einzelner Test ist verlässlich. Entscheidend sind Anamnese, Risikofaktoren und das klinische Gesamtbild."], "q": "Rushton 2023"}, "frt": {"t": "Flexions-Rotations-Test", "x": ["Rückenlage, HWS passiv voll gebeugt, damit die unteren Segmente sperren. Dann Rotation zu beiden Seiten, die vor allem in C1/C2 stattfindet.", "Normal etwa 44° pro Seite. Positiv bei unter 32° oder mehr als 10° unter dem Normalwert."], "q": "Hall 2010"}, "ndi": {"t": "Neck Disability Index", "x": ["10 Fragen, 0–50 Punkte oder 0–100 %, höher ist schlechter.", "Spürbare Änderung je nach Studie 5–33 %, typisch etwa 7,5 Punkte (15 %)."], "q": "Fragebogen"}, "andersen": {"t": "Andersen 2012", "x": ["Cluster-RCT mit 447 Büroangestellten: 1 h Nacken-Schulter-Krafttraining pro Woche über 20 Wochen.", "Ob 1 × 60, 3 × 20 oder 9 × 7 Minuten, machte für den Schmerz keinen Unterschied."], "q": "Br J Sports Med 2012"}, "dezoete": {"t": "de Zoete 2021", "x": ["Netzwerk-Metaanalyse mit 40 RCTs zu Übungsformen bei chronischem Nackenschmerz.", "Motorkontrolle, Yoga, Pilates, Tai Chi, Qigong und Krafttraining wirkten etwa gleich gut, bei sehr niedriger Qualität der Evidenz."], "q": "Br J Sports Med 2021"}, "rasmussen": {"t": "Rasmussen-Barr 2023", "x": ["Übersicht über 25 systematische Reviews mit über 17.000 Teilnehmenden.", "Alle Übungsformen senkten kurzfristig den Schmerz. Bei der Beeinträchtigung zeigte Krafttraining allein keinen klaren Effekt, die anderen Formen schon. Eine beste Form lässt sich nicht benennen."], "q": "BMC Musculoskelet Disord 2023"}, "peters": {"t": "Peters 2025", "x": ["Systematischer Review von 19 Leitlinien zu Nackenschmerz, 5 davon hochwertig.", "Alle hochwertigen empfehlen Mobilisation oder Manipulation. Von allen 19 beschreiben nur 2 das Screening auf Gefäßrisiken vollständig."], "q": "Phys Ther 2025"}}}, {"id": "w48-rad", "titel": "Lumbale Radikulopathie und Bandscheibenvorfall", "art": "kb", "kb": "WS02", "min": 12, "abschnitte": [{"t": "1. Was ist das eigentlich?", "b": [{"p": ["Gewebe aus dem Nucleus pulposus tritt durch den Faserring aus und drückt auf eine lumbale Nervenwurzel, meist L5 (bei LWK4/5) oder S1 (bei LWK5/SWK1). Der Beinschmerz entsteht durch den Druck und zusätzlich durch eine chemische Reizung der Wurzel. Darum passen Bildbefund und Beschwerden oft nicht zusammen."]}, {"l": ["[[Radikulärer Schmerz und Radikulopathie|radikulaer]] sind zu trennen: Radikulärer Schmerz strahlt ins Dermatom aus, bei der Radikulopathie kommen Ausfälle dazu. Die Ausfälle bestimmen, wie dringend es ist.", "Auslöser ist oft Heben in Beugung und Rotation, auf dem Boden einer Degeneration des Faserrings.", "Vorfälle finden sich auch bei Gesunden häufig: Protrusionen bei 29 % der 20-Jährigen und 43 % der 80-Jährigen ohne Beschwerden ([[Brinjikji 2015|brinjikji]])."]}]}, {"t": "2. Wurzeln, Kennmuskeln und Verlauf", "b": [{"tab": [["L3", "Quadrizeps, Hüftbeuger, Adduktoren. PSR. Ausstrahlung bis zum Knie"], ["L4", "Quadrizeps, Hüftbeuger. PSR. Tibiavorderkante"], ["L5", "Großzehen- und Fußheber, Gluteus medius. Tibialis-posterior-Reflex. Unterschenkel außen, Fußrücken bis Großzehe"], ["S1", "Fußsenker, Gluteus maximus. ASR. Wade bis Fußaußenrand"]]}, {"bars": [["Deutlich besser in 6–12 Wochen", 70, "60–80 % ohne OP"], ["Sequester bilden sich zurück", 96, "gerade große Vorfälle am häufigsten"], ["Extrusionen bilden sich zurück", 70, ""], ["Nach 5 Jahren nicht erholt", 8, "mit und ohne OP gleich"]]}, {"p": ["In der Primärversorgung ist nach 12 Monaten nur gut die Hälfte gebessert, ein Teil behält wechselnde Beschwerden (ATLAS, Konstantinou 2018). Am stärksten ungünstig sind eine lange Dauer des Beinschmerzes und die Überzeugung, dass es lange dauern wird. Der MRT-Befund sagt den Verlauf kaum voraus."], "merk": "Gerade große Vorfälle bilden sich am häufigsten zurück. Das ist eine gute Nachricht für den Patienten."}]}, {"t": "3. Red Flags zuerst", "b": [{"tab": [["Cauda-equina-Zeichen", "Neue Probleme beim Wasserlassen, Taubheit im Gesäß- oder Genitalbereich, Verlust des Rektumgefühls, sexuelle Störung, Ausfälle an beiden Beinen. Sofort Notaufnahme"], ["Schwere Parese", "Kraftgrad 3/5 oder schlechter oder zunehmend. Am selben Tag ärztlich"], ["Schmerz lässt nach, Parese bleibt", "Kann auf einen Wurzeltod hinweisen. Ärztlich"], ["Plötzlich beidseitiger Beinschmerz", "Dringlich ärztlich"], ["Sonstige Warnzeichen", "Tumoranamnese, Fieber, Gewichtsverlust, Trauma bei Osteoporose, Nachtschmerz"]]}, {"p": ["Das [[Cauda-equina-Syndrom|ces]] ist selten, 1–3 je 100.000 Menschen pro Jahr. Die klassischen Zeichen sind wenig sensitiv (19–43 %), ihr Fehlen schließt es nicht aus. Der britische Versorgungspfad von 2023 verlangt bei neuen Symptomen die sofortige Notaufnahme und ein MRT innerhalb von 4 Stunden."], "merk": "Blase und Darm bei jedem Ischias-Patienten aktiv erfragen, auch wenn er es nicht selbst anspricht."}]}, {"t": "4. Befund und Abgrenzung", "b": [{"l": ["Anamnese: Rücken- und Beinschmerz getrennt erfassen, Blase und Darm, psychosoziale Faktoren.", "Kennmuskeln im Seitenvergleich. Eine leichte Fußsenkerschwäche fällt erst beim einbeinigen Zehenstand auf, eine leichte Quadrizepsschwäche beim Stufensteigen. Gluteen mitprüfen.", "Reflexe und Sensibilität ergänzen, sie sind weniger ergiebig als die Motorik.", "Lasègue, gekreuzter Lasègue, Slump. Bei hohen Wurzeln den Femoralis-Dehnungstest."]}, {"p": ["Der Lasègue ist sehr sensitiv (92 %), aber kaum spezifisch (28 %). Ein negativer Test macht einen relevanten Vorfall unwahrscheinlicher. Der gekreuzte Lasègue ist umgekehrt spezifisch (90 %) und bestätigt eher ([[Cochrane 2010|windt]]). Die Daten stammen fast nur aus chirurgischen Patientengruppen, mehrere Befunde zusammen sagen mehr als einer allein."]}, {"tab": [["Nicht-spezifischer Kreuzschmerz", "Ausstrahlung höchstens bis zum Knie, Neurologie unauffällig"], ["Spinalkanalstenose", "älter, Beschwerden beim Gehen, besser beim Vorbeugen"], ["Pseudoradikulär (Hüfte, ISG, Facetten)", "Neurologie unauffällig, Schmerz nicht im Dermatom"], ["Polyneuropathie", "beidseits, strumpfförmig, langsamer Beginn"], ["Entzündung, Zoster, Borrelien, Tumor", "Nachtschmerz, bewegungsunabhängig, ohne Nervendehnungszeichen. Ärztlich"]]}, {"l": ["Messen: NRS für Bein und Rücken getrennt (spürbar 2 Punkte oder 30 %), ODI 10 Punkte, RMDQ 5 Punkte ([[Ostelo 2008|ostelo]]).", "Kraftgrade bei jedem Termin kurz prüfen und dokumentieren."]}]}, {"t": "5. Bildgebung", "b": [{"p": ["Ohne Warnzeichen anfangs kein MRT. Es kommt erst, wenn es nach 6–8 Wochen nicht besser wird oder eine OP in Frage steht."], "fig": [{"src": "fortbildung/bilder/2026-W47/ana-lws-prolaps.webp", "t": "Posterolateraler Bandscheibenvorfall, Blick von oben.", "c": "1 Vorfall des Nucleus durch den Faserring, 2 bedrängte Nervenwurzel, 3 Duralsack mit Cauda equina, 4 Facettengelenk. Vorne liegt im Bild unten."}], "merk": "Das hintere Längsband deckt in der LWS nur die Mitte ab, Vorfälle gehen deshalb meist posterolateral. Ein Vorfall L4/5 trifft dann die Wurzel L5, ein Vorfall L5/S1 die Wurzel S1."}, {"p": ["KI-erstellte Lehrbilder nach typischen Lehrbuchfällen, geprüft, keine echten Aufnahmen."]}]}, {"t": "6. Was hilft laut Studienlage?", "b": [{"p": ["Die deutschen Leitlinien sind abgelaufen: die DGN-Leitlinie 030-058 seit Januar 2023, die [[S2k 187-057|s2k]] seit Juli 2025, sie ist in Überarbeitung. NICE NG59 ist evidenzbasiert und wurde am 29.07.2026 zuletzt geändert. Alle setzen auf Aufklärung, aktiv bleiben und aktive Physiotherapie."]}, {"l": ["Akut: aktiv bleiben, Bettruhe höchstens kurz (nicht über 4 Tage). Richtungspräferenz testen, zum Beispiel wiederholte Extension in Bauchlage, wenn der Beinschmerz zentralisiert.", "Frühe Physiotherapie über 4 Wochen (Übungen plus manuelle Therapie) senkte den ODI nach 6 Monaten um 5 Punkte, ein kleiner, aber messbarer Effekt (Fritz 2021).", "Übungen statt nur „aktiv bleiben“ bringen nur kurzfristig einen kleinen Vorteil beim Beinschmerz. McKenzie und Neurodynamik sind nicht besser belegt als gute aktive Therapie.", "OP oder konservativ: Eine frühe OP lindert schneller, nach 1, 2 und 5 Jahren gibt es keinen Unterschied ([[Peul 2007|peul]]). Bei Ischias seit 4–12 Monaten war die OP besser als weitere konservative Behandlung (Beinschmerz 2,8 gegen 5,2 nach 6 Monaten, Bailey 2020).", "Pregabalin und Gabapentin wirken bei Ischias nicht besser als Placebo (PRECISE, Mathieson 2017). NICE rät ab.", "Epidurale Kortisoninjektion: kurzfristig etwa 5 von 100 Punkten weniger Beinschmerz (Cochrane 2020). Das ist eine ärztliche Entscheidung.", "Nach Mikrodiskektomie: Übungsprogramm ab Woche 4–6, eher intensiv, betreut oder zu Hause gleich gut (Cochrane, Oosterhuis 2014). Pauschale Sitz- oder Hebeverbote sind nicht nötig."]}, {"tab": [["Nicht empfohlen", "Bettruhe über 4 Tage, Manipulation im betroffenen Segment, Traktion in der Akutphase"], ["Akut nicht", "Elektrotherapie, Massage, Akupunktur (S2k 187-057)"], ["Bei NICE nicht", "TENS, Ultraschall, Interferenzstrom, Korsetts"]], "merk": "Die meisten werden ohne OP besser. Eine OP macht es schneller, aber nach einem Jahr nicht besser."}]}, {"t": "7. Was neu ist", "b": [{"l": ["[[Zhu 2025|zhu]]: Zwei Netzwerk-Metaanalysen zur nicht-operativen Behandlung, akut und subakut (40 RCTs) und chronisch (50 RCTs). Die Evidenz hatte durchgehend sehr niedriges Vertrauen, keine Maßnahme ist klar besser belegt als eine andere.", "Dove 2023 kam mit 18 RCTs zum selben Bild: Physiotherapie gegen Kontrollen insgesamt ohne klaren Unterschied, gegen reine Beratung langfristig etwas weniger Schmerz.", "NICE hat NG59 am 29.07.2026 geändert und zwei Empfehlungen zu psychologischer Therapie und kombinierten Programmen gestrichen.", "Seit Juni 2025 gibt es die deutsche [[S3-Leitlinie Epidurale Injektionen|s3epi]] (AWMF 151-005, gültig bis 22.06.2030)."], "merk": "Die Studienlage ist dünn. Umso wichtiger sind gute Aufklärung, Aktivität und das Beobachten der Neurologie."}]}, {"t": "8. Für den Praxisalltag", "b": [{"l": ["Bei jedem Termin Kraftgrade der Kennmuskeln kurz prüfen, zum Beispiel einbeiniger Zehenstand und Großzehenheber.", "Blase, Darm und Reithosengefühl erfragen und dokumentieren.", "Neurodynamik als Gleiten (Slider) statt Spannen, 2–3 × 10, schmerzfrei.", "Gehen in kurzen Einheiten mehrmals täglich, langsam steigern.", "Belastung erst steigern, wenn der Beinschmerz zentralisiert oder abnimmt.", "Keine Besserung nach 6–12 Wochen: die OP-Frage ärztlich klären lassen.", "Nach Mikrodiskektomie Klinikvorgaben beachten, manuelle Therapie im operierten Segment mindestens 6 Wochen meiden (Expertenmeinung)."], "merk": "Fürs Patientengespräch: „Gerade große Vorfälle bilden sich am häufigsten zurück. Die meisten werden ohne OP besser. Wichtig ist, dass wir Ihre Kraft im Bein im Blick behalten.“"}]}], "quellen": ["DGOOC/DGOU S2k Bandscheibenvorfälle mit radikulärer Symptomatik, AWMF 187-057 (früher 033-048), gültig bis 30.07.2025, in Überarbeitung", "DGN S2k Lumbale Radikulopathie, AWMF 030-058, abgelaufen 10.01.2023", "NICE NG59 Low back pain and sciatica, 2016, Medikamente 2020, Änderung 29.07.2026", "GIRFT National Suspected Cauda Equina Syndrome Pathway 2023", "van der Windt DA et al. Cochrane 2010 (klinische Untersuchung)", "Peul WC et al. N Engl J Med 2007; Bailey CS et al. N Engl J Med 2020", "Fritz JM et al. Ann Intern Med 2021; Mathieson S et al. N Engl J Med 2017 (PRECISE)", "Oosterhuis T et al. Cochrane 2014 (Reha nach Bandscheiben-OP); Cochrane 2020 (epidurale Steroide)", "Konstantinou K et al. 2018 (ATLAS); Brinjikji W et al. AJNR 2015; Ostelo RW et al. Spine 2008", "Zhu Z et al. JOSPT 2025 und J Pain 2025 (Netzwerk-Metaanalysen); Dove L et al. Eur Spine J 2023", "S3 Epidurale Injektionen bei degenerativen Erkrankungen, AWMF 151-005, 2025, gültig bis 22.06.2030"], "fragen": [["Welche Wurzel wird bei einem posterolateralen Vorfall in Höhe L4/5 meist bedrängt (Ziffer 2)?", ["L4", "S1", "L5", "L3"], 2, "Der posterolaterale Vorfall trifft die Wurzel, die eine Etage tiefer austritt. Bei L4/5 ist das meist L5, bei L5/S1 meist S1.", "fortbildung/bilder/2026-W47/ana-lws-prolaps.webp"], ["Welcher Test deckt eine leichte Schwäche der Wurzel S1 am besten auf?", ["Fersengang", "Einbeiniger Zehenstand mehrmals hintereinander", "Großzehe gegen Widerstand heben", "Stufensteigen"], 1, "S1 versorgt die Fußsenker. Eine leichte Schwäche fällt erst bei wiederholtem einbeinigem Zehenstand auf."], ["Welcher Test ist bei Bandscheibenvorfall eher spezifisch?", ["Lasègue", "Gekreuzter Lasègue", "Slump-Test", "Femoralis-Dehnungstest"], 1, "Der gekreuzte Lasègue hat eine Spezifität von etwa 90 %, ist aber wenig sensitiv. Der normale Lasègue ist sensitiv (92 %), aber kaum spezifisch."], ["Was stimmt beim Verdacht auf ein Cauda-equina-Syndrom?", ["Erst abwarten, ob es sich in 2 Tagen bessert", "Fehlen die klassischen Zeichen, ist es ausgeschlossen", "Sofort in die Notaufnahme, MRT innerhalb von 4 Stunden", "Erst ein Röntgen beim Hausarzt"], 2, "Der britische Pfad 2023 verlangt die sofortige Notaufnahme. Die klassischen Zeichen sind wenig sensitiv, ihr Fehlen schließt nichts aus."], ["Ein Patient hat eine Fußheberschwäche Kraftgrad 3/5. Was ist richtig?", ["Weiter Physiotherapie, in 4 Wochen neu prüfen", "Erst nach 6 Wochen ein MRT", "Nur Kräftigung, das reicht", "Am selben Tag ärztlich vorstellen"], 3, "Eine Parese mit Kraftgrad 3/5 oder schlechter oder eine zunehmende Parese gehört am selben Tag ärztlich abgeklärt."], ["Was zeigte Peul 2007 beim Vergleich frühe OP gegen konservativ?", ["OP ist nach einem Jahr deutlich besser", "OP lindert schneller, nach einem Jahr kein Unterschied", "Konservativ ist in allem besser", "Nach OP gibt es mehr Rückfälle"], 1, "Nach OP sank der Schmerz schneller. Nach einem Jahr waren in beiden Gruppen etwa 95 % erholt."], ["Wie oft bilden sich Sequester zurück?", ["In etwa 96 %", "Fast nie", "Etwa in einem Drittel", "Etwa in der Hälfte"], 0, "Gerade große, sequestrierte Vorfälle bilden sich am häufigsten zurück, in etwa 96 %. Extrusionen in etwa 70 %."], ["Was zeigte die PRECISE-Studie zu Pregabalin bei Ischias?", ["Nicht besser als Placebo", "Deutlich weniger Beinschmerz", "Nur in Kombination mit Kortison wirksam", "Besser als Physiotherapie"], 0, "Pregabalin war bei Ischias nicht besser als Placebo, hatte aber mehr Nebenwirkungen. NICE rät von Pregabalin und Gabapentin ab."], ["Wann ist bei Ischias ohne Warnzeichen ein MRT sinnvoll?", ["Sofort beim ersten Termin", "Nie", "Nur bei Rückenschmerz ohne Beinschmerz", "Erst wenn es nach 6–8 Wochen nicht besser wird"], 3, "Ohne Warnzeichen anfangs kein MRT. Es kommt, wenn es nach 6–8 Wochen nicht besser wird oder eine OP in Frage steht."], ["Welche Änderung im ODI gilt als spürbar?", ["2 Punkte", "5 Punkte", "10 Punkte", "30 Punkte"], 2, "Nach Ostelo 2008 gelten 10 Punkte im ODI als spürbar, 5 Punkte im RMDQ, 2 Punkte oder 30 % auf der NRS."], ["Wie soll Neurodynamik bei akuter Radikulopathie dosiert werden?", ["Maximal spannen, bis der Schmerz einschießt", "Gar nicht, Nerven nie bewegen", "Nur passiv durch den Therapeuten", "Als Gleiten (Slider), schmerzfrei"], 3, "Gleiten statt Spannen, 2–3 × 10 Wiederholungen ohne Schmerzverstärkung."], ["Ab wann beginnt nach Mikrodiskektomie meist das strukturierte Übungsprogramm?", ["Ab Woche 4–6", "Ab dem OP-Tag mit Krafttraining", "Erst nach 6 Monaten", "Gar nicht, Schonung reicht"], 0, "Gehen und Mobilisieren gleich nach der OP, das strukturierte Übungsprogramm ab Woche 4–6. Übungen führten nicht zu mehr Reoperationen."], ["Was fanden die Netzwerk-Metaanalysen von Zhu 2025 zur nicht-operativen Behandlung bei Ischias?", ["Manuelle Therapie ist klar am besten", "Nur Medikamente helfen", "Die Evidenz ist sehr unsicher, keine Maßnahme ist klar überlegen", "Bettruhe ist am wirksamsten"], 2, "Einzelne Maßnahmen zeigten kurzfristig Effekte, aber alle Ergebnisse hatten sehr niedriges Vertrauen."]], "info": {"radikulaer": {"t": "Radikulärer Schmerz und Radikulopathie", "x": ["Radikulärer Schmerz: ausstrahlender Schmerz im Dermatom ohne neurologisches Defizit.", "Radikulopathie: mit Ausfällen bei Kraft, Reflex oder Sensibilität. Die Ausfälle bestimmen, wie dringend ärztlich abgeklärt wird."], "q": "S2k 187-057"}, "brinjikji": {"t": "Brinjikji 2015", "x": ["Metaanalyse mit 3110 Menschen ohne Rückenschmerzen.", "Protrusionen bei 29 % der 20-Jährigen und 43 % der 80-Jährigen, Bandscheibendegeneration bei 37–96 %."], "q": "AJNR 2015"}, "ces": {"t": "Cauda-equina-Syndrom", "x": ["Kompression mehrerer Wurzeln der Cauda equina, 1–3 je 100.000 Menschen pro Jahr.", "Klassische Zeichen sind wenig sensitiv (19–43 %). Britischer Pfad 2023: bei neuen Symptomen sofort Notaufnahme, MRT binnen 4 Stunden."], "q": "GIRFT 2023"}, "windt": {"t": "Cochrane 2010 (van der Windt)", "x": ["Übersicht zur Genauigkeit der klinischen Untersuchung bei Bandscheibenvorfall.", "Lasègue: Sensitivität 0,92, Spezifität 0,28. Gekreuzter Lasègue: Sensitivität 0,28, Spezifität 0,90."], "q": "Cochrane 2010"}, "ostelo": {"t": "Ostelo 2008", "x": ["Internationaler Konsens zu spürbaren Änderungen bei Rückenschmerz.", "NRS 2 Punkte, RMDQ 5, ODI 10, oder 30 % besser als am Anfang."], "q": "Spine 2008"}, "s2k": {"t": "S2k 187-057", "x": ["Leitlinie der DGOOC zur konservativen, operativen und rehabilitativen Versorgung bei Bandscheibenvorfällen mit radikulärer Symptomatik (früher 033-048).", "Konsens ohne systematische Evidenzbewertung, gültig bis 30.07.2025, in Überarbeitung."], "q": "AWMF 187-057"}, "peul": {"t": "Peul 2007", "x": ["RCT mit 283 Patienten mit schwerer Ischias seit 6–12 Wochen: frühe OP gegen verlängert konservativ.", "Nach OP schnellere Schmerzlinderung, nach 1 Jahr in beiden Gruppen 95 % erholt. 39 % der konservativ Behandelten wurden später operiert."], "q": "N Engl J Med 2007"}, "zhu": {"t": "Zhu 2025", "x": ["Zwei Netzwerk-Metaanalysen: akut und subakut 40 RCTs mit 5381 Teilnehmenden (JOSPT), chronisch 50 RCTs mit 4920 Teilnehmenden (J Pain).", "Die gesamte Evidenz hatte sehr niedriges Vertrauen. Keine nicht-operative Behandlung ist klar besser belegt als eine andere."], "q": "JOSPT 2025; J Pain 2025"}, "s3epi": {"t": "S3 Epidurale Injektionen", "x": ["S3-Leitlinie Epidurale Injektionen bei degenerativen Erkrankungen, AWMF 151-005, federführend die Deutsche Wirbelsäulengesellschaft.", "Version 1.0 vom 23.06.2025, gültig bis 22.06.2030. Die Injektion ist eine ärztliche Entscheidung."], "q": "AWMF-Register 151-005"}}}, {"id": "w48-rm", "titel": "Rotatorenmanschetten-Tendinopathie", "art": "kb", "kb": "SH01", "min": 11, "abschnitte": [{"t": "1. Was ist das eigentlich?", "b": [{"p": ["Die Sehnen der Rotatorenmanschette sind mehr belastet, als sie gerade vertragen, und reagieren mit einer [[Tendinopathie|tendinopathie]]. Der Schleimbeutel unter dem Schulterdach kann mitgereizt sein. Früher hieß das Impingement. Die Enge unter dem Akromion erklärt die Beschwerden aber schlechter als lange gedacht."]}, {"l": ["Die US-Leitlinie [[JOSPT 2025|jospt]] fasst subakromiales Schmerzsyndrom, Impingement, Bursitis, Tendinopathie der langen Bizepssehne und Partialrupturen zusammen. Komplette Rupturen und die Schultersteife gehören nicht dazu.", "Die deutsche [[S2e-Leitlinie|s2e]] spricht noch von subakromialem Impingement. Sie galt bis 19.11.2026, eine Überarbeitung ist offen.", "16–21 % haben gerade oder im letzten Jahr Schulterschmerz, mehr als die Hälfte davon geht auf die Rotatorenmanschette. Etwa 38 neue Fälle je 1000 Personen pro Jahr.", "Typisch sind Überkopfarbeit, Wurf- und Schwimmsport und eine schnelle Laststeigerung. Frauen sind etwas häufiger betroffen.", "34 % der Beschwerdefreien haben einen Sehnenbefund im Ultraschall. Der Befund allein erklärt den Schmerz also nicht."]}]}, {"t": "2. Typische Symptome und Verlauf", "b": [{"l": ["Schmerz seitlich am Oberarm, oft bis zum Ansatz des M. deltoideus", "Schmerzhafter Bogen beim seitlichen Heben, etwa zwischen 60° und 120°", "Nachtschmerz beim Liegen auf der betroffenen Seite", "Schmerz bei Widerstand gegen Abduktion und Außenrotation, die Kraft ist eher erhalten", "Passiv weitgehend frei beweglich, anders als bei der Frozen Shoulder"]}, {"bars": [["Nach 1 Monat erholt", 23, "Schulterschmerz allgemein in der Hausarztpraxis"], ["Nach 1 Jahr erholt", 59, "41 % haben noch Beschwerden"]]}, {"p": ["Die meisten sind nach etwa 3 Monaten deutlich besser. Die Zahlen oben stammen aus [[van der Windt 1996|windt]] und gelten für Schulterschmerz allgemein. Ungünstig sind Alter über 55, hohe Arbeitsbelastung, starker Schmerz zu Beginn, gleichzeitiger Nackenschmerz und eine lange Dauer."], "merk": "Die Sehne ist überlastet, nicht kaputt. Sie wird wieder belastbar, wenn die Last Schritt für Schritt steigt."}]}, {"t": "3. Befund und Abgrenzung", "b": [{"l": ["HWS screenen und Warnzeichen abfragen.", "Aktiv gegen passiv: Passiv weitgehend frei spricht gegen eine Frozen Shoulder.", "Kraft der Außenrotation und Abduktion mit dem Handdynamometer messen, nicht nach Gefühl. Erst Unterschiede über 15–20 % sind sicher mehr als Messfehler.", "Provokationstests immer im Cluster deuten, nie einzeln."]}, {"tab": [["Painful Arc", "LR+ 3,4, LR− 0,46: bestätigt eher"], ["Hawkins-Kennedy", "LR+ 2,7, LR− 0,25: negativ schließt eher aus"], ["Neer", "LR+ 1,5, LR− 0,68: wenig Nutzen"], ["3 von 5 Tests positiv", "LR+ 2,9, LR− 0,34 (Hawkins, Neer, Painful Arc, Jobe, Außenrotation gegen Widerstand)"]]}, {"tab": [["Komplette Ruptur", "Trauma, deutliche Schwäche, Arm fällt. Lag Signs, Drop Arm, Ultraschall"], ["Frozen Shoulder", "passiv ebenso eingeschränkt, Außenrotation am stärksten"], ["Kalkschulter", "plötzlicher, sehr starker Schmerz. Röntgen zeigt das Depot"], ["ACG-Arthrose", "Schmerz oben auf der Schulter, Arm quer vor dem Körper"], ["Instabilität", "jünger, Überkopfsport, Gefühl des Wegrutschens"], ["Zervikale Radikulopathie", "Ausstrahlung unter den Ellenbogen, Kribbeln"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-sch-subakromial.webp", "t": "Subakromialer Raum, rechte Schulter von vorne-lateral.", "c": "1 Akromion, 2 Lig. coracoacromiale, 3 Bursa subacromialis, 4 Supraspinatussehne, 5 Tuberculum majus."}], "merk": "Bildgebung erst, wenn es nach höchstens 12 Wochen nicht besser wird, früher nur bei Trauma oder Verdacht auf komplette Ruptur. Ultraschall vor MRT."}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."]}]}, {"t": "4. Reizbarkeit und Messen", "b": [{"p": ["Ein geprüftes Stufenmodell gibt es für die Rotatorenmanschette nicht. [[STAR-Shoulder|star]] schlägt drei Stufen vor. Die Tabelle ist eine Orientierung, Expertenmeinung."]}, {"tab": [["Hoch", "NAS 7 oder mehr, regelmäßig Nachtschmerz, schon leichte Last provoziert lange"], ["Mittel", "NAS 4–6, zeitweise nachts, Schmerz bei Last klingt bis zum nächsten Tag ab"], ["Niedrig", "NAS 3 oder weniger, kaum nachts, nur hohe oder Überkopflast stört"]]}, {"l": ["[[SPADI|spadi]] oder QuickDASH zu Beginn und alle 4 Wochen. Spürbar besser ab etwa 8–13 Punkten im SPADI.", "Kraft Außenrotation und Abduktion in kg im Seitenvergleich.", "Schmerz bei der schwierigsten Alltagsbewegung auf der NAS."]}]}, {"t": "5. Was hilft laut Studienlage?", "b": [{"p": ["Aktive Übungen sind die Erstbehandlung (JOSPT Grad A, S2e „soll“). Entscheidend ist, dass die Last steigt. [[Progressives Krafttraining|progressiv]] senkte den Schmerz um gut einen Punkt auf der 10er-Skala, Übungen ohne Steigerung brachten nichts."]}, {"l": ["[[Holmgren 2012|holmgren]]: 102 Patienten auf der OP-Warteliste. Nach 12 Wochen exzentrischer Übungen für Rotatorenmanschette und Schulterblatt wollten nur noch 20 % operiert werden, in der Kontrollgruppe 63 %.", "Schwer oder leicht trainieren macht kaum einen Unterschied ([[Ingwersen 2017|ingwersen]]). Unter Anleitung ist nicht besser als zu Hause.", "Hohe Reizbarkeit: Isometrie für Außenrotation und Abduktion, 5 × 30–45 s (Expertenmeinung), Last anpassen statt Ruhe, ärztlich eine Injektion besprechen.", "Mittlere Reizbarkeit: exzentrisch Supraspinatus und Außenrotatoren 3 × 15, Schulterblattmuskeln, Last etwa alle 2 Wochen steigern.", "Niedrige Reizbarkeit: schwerer und über Schulterhöhe trainieren, 3 × 8–12, dann arbeits- oder sportspezifisch.", "Manuelle Therapie bringt einen kleinen, kurzfristigen Zusatzeffekt.", "Kortisoninjektion hilft etwa 4–8 Wochen, etwa jeder Fünfte profitiert, danach kein Unterschied mehr."]}, {"tab": [["Nicht empfohlen", "therapeutischer Ultraschall, Stoßwelle ohne Kalk, PRP, Hyaluronsäure"], ["Operation", "[[Subakromiale Dekompression|sad]] war nicht besser als eine Schein-OP oder Training"]], "merk": "Schmerzregel nach Holmgren: bis 5 von 10 während der Übung erlaubt, bis zur nächsten Einheit wieder auf dem Ausgangsniveau."}]}, {"t": "6. Für den Praxisalltag", "b": [{"l": ["Erst die Reizbarkeit einstufen, dann die Intensität danach wählen.", "Heimprogramm über 12 Wochen planen, 1–2× täglich, Kontrolle alle 1–2 Wochen.", "Last alle etwa 2 Wochen steigern, sobald die Wiederholungen sauber gehen.", "Nach 6–8 Wochen ohne Fortschritt eine Injektion ärztlich besprechen, nach höchstens 12 Wochen ohne Besserung Bildgebung und fachärztliche Abklärung.", "Eine OP frühestens nach 6 Monaten konservativer Therapie (BESS). Die S2e empfiehlt sie dann noch, die Placebo-Studien sprechen dagegen."], "merk": "Fürs Patientengespräch: „Die Sehne ist überlastet, nicht kaputt. Sie wird wieder belastbar, wenn wir sie Schritt für Schritt mehr fordern. Das dauert meist etwa drei Monate.“"}]}], "quellen": ["Desmeules F et al. Rotator cuff tendinopathy: clinical practice guideline. JOSPT 2025", "DGOU/DVSE S2e Subakromiales Impingement, AWMF 187-060, 2021, gültig bis 19.11.2026", "BESS Patient Care Pathway Subacromial Pain 2025; BMJ Rapid Recommendation 2019", "Holmgren T et al. BMJ 2012; Ingwersen KG et al. 2017", "van der Windt DA et al. 1996; McClure PW, Michener LA. Phys Ther 2015 (STAR-Shoulder)"], "fragen": [["Wo liegt der schmerzhafte Bogen bei der Rotatorenmanschetten-Tendinopathie typischerweise?", ["0–30° Abduktion", "Nur über 160°", "Etwa 60–120° Abduktion", "Nur in Außenrotation"], 2, "Der Painful Arc liegt etwa zwischen 60° und 120°. Schmerz erst endgradig spricht eher für das AC-Gelenk."], ["Welcher Befund spricht gegen eine Frozen Shoulder und für die Tendinopathie?", ["Passiv weitgehend frei beweglich", "Passive Außenrotation stark eingeschränkt", "Nachtschmerz", "Schmerz seitlich am Oberarm"], 0, "Bei der Tendinopathie ist die passive Beweglichkeit weitgehend frei. Bei der Frozen Shoulder ist sie passiv genauso eingeschränkt, die Außenrotation am stärksten."], ["Welcher Test hilft vor allem beim Ausschließen, wenn er negativ ist?", ["Neer", "Painful Arc", "Drop Arm", "Hawkins-Kennedy"], 3, "Hawkins-Kennedy hat ein LR− von 0,25. Ist er negativ, wird die Diagnose unwahrscheinlicher."], ["Was zeigte Holmgren 2012 bei Patienten auf der OP-Warteliste?", ["Alle wollten nach dem Training noch operiert werden", "Training verschlechterte den Schmerz", "Nach Training wollten nur 20 % statt 63 % operiert werden", "Nur die Injektion wirkte"], 2, "Nach 12 Wochen exzentrischer Übungen für Rotatorenmanschette und Schulterblatt entschieden sich nur 20 % für eine OP, in der Kontrollgruppe 63 %."], ["Was ist beim Training der Rotatorenmanschette laut Studienlage entscheidend?", ["Dass die Last steigt", "Dass möglichst schwer trainiert wird", "Dass immer ein Therapeut dabei ist", "Dass nur isometrisch trainiert wird"], 0, "Progressive Last wirkt, Übungen ohne Steigerung brachten nichts. Schwer gegen leicht und betreut gegen zu Hause machten kaum einen Unterschied."], ["Wie lange hilft eine subakromiale Kortisoninjektion etwa?", ["Einen Tag", "Mindestens ein Jahr", "Dauerhaft", "Etwa 4–8 Wochen"], 3, "Sie hilft etwa 4–8 Wochen, etwa jeder Fünfte profitiert. Danach ist kein Unterschied mehr da, wiederholte Spritzen sind nicht besser."], ["Was ist mit der 3 markiert?", ["Supraspinatussehne", "Lig. coracoacromiale", "Akromion", "Bursa subacromialis"], 3, "Die 3 ist die Bursa subacromialis zwischen Schulterdach und Supraspinatussehne. Sie kann bei der Tendinopathie mitgereizt sein.", "fortbildung/bilder/2026-W47/ana-sch-subakromial.webp"], ["Was zeigten die Placebo-Studien zur subakromialen Dekompression?", ["Deutlich besser als Training", "Nicht besser als Schein-OP oder Training", "Nur bei Frauen wirksam", "Besser als Schein-OP, schlechter als Training"], 1, "In CSAW und FIMPACT war die Dekompression nach einem Jahr nicht besser als eine Schein-OP. Die BMJ-Empfehlung 2019 rät stark ab."], ["Wie lautet die Schmerzregel aus Holmgren 2012?", ["Übungen nur völlig schmerzfrei", "Bis 5 von 10 erlaubt, bis zur nächsten Einheit zurück auf das Ausgangsniveau", "Bis 8 von 10 erlaubt, solange es am Abend besser ist", "Schmerz spielt keine Rolle"], 1, "Bis 5 von 10 während der Übung, bis zur nächsten Einheit wieder auf dem Ausgangsniveau. Sonst Last reduzieren."], ["Wann ist Bildgebung bei Verdacht auf Rotatorenmanschetten-Tendinopathie sinnvoll?", ["Immer beim ersten Termin", "Nie", "Nach höchstens 12 Wochen ohne Besserung oder nach Trauma", "Nur ein MRT vor jedem Training"], 2, "Zu Beginn keine Bildgebung. Ultraschall erst nach höchstens 12 Wochen ohne Besserung, früher bei Trauma oder Verdacht auf komplette Ruptur."], ["Ab wie vielen Punkten Besserung im SPADI spürt der Patient etwas?", ["Etwa 8–13 Punkte", "1–2 Punkte", "Mindestens 40 Punkte", "Erst bei 0 Punkten"], 0, "Die kleinste spürbare Besserung im SPADI liegt bei etwa 8–13 Punkten."], ["Wie viele Beschwerdefreie haben einen Sehnenbefund im Ultraschall?", ["Fast niemand", "Etwa 34 %", "Etwa 90 %", "Nur Leistungssportler"], 1, "Etwa jeder Dritte ohne Beschwerden hat einen Sehnenbefund. Der Ultraschall allein erklärt den Schmerz deshalb nicht."]], "info": {"tendinopathie": {"t": "Tendinopathie", "x": ["Schmerzhafte Sehne mit veränderter Struktur und geringerer Belastbarkeit, meist ohne klassische Entzündung.", "Sie reagiert auf dosierte, steigende Last, nicht auf Schonung."], "q": "JOSPT 2025"}, "jospt": {"t": "JOSPT 2025", "x": ["Klinische Leitlinie der amerikanischen Physiotherapie-Fachgesellschaft zur Rotatorenmanschetten-Tendinopathie, Desmeules et al., April 2025.", "Grad A = starke Evidenz, F = Expertenmeinung."], "q": "Desmeules 2025"}, "s2e": {"t": "S2e-Leitlinie", "x": ["Deutsche Leitlinie „Subakromiales Impingement“ von DGOU und DVSE, 2021.", "Gültig bis 19.11.2026, also gerade abgelaufen. Sie ist chirurgisch geprägt und empfiehlt nach gescheiterter Physiotherapie noch die Dekompression."], "q": "AWMF 187-060"}, "windt": {"t": "van der Windt 1996", "x": ["349 neue Schulterschmerz-Episoden in niederländischen Hausarztpraxen.", "Nach 1 Monat 23 %, nach 1 Jahr 59 % erholt. Gilt für Schulterschmerz allgemein."], "q": "BJGP 1996"}, "star": {"t": "STAR-Shoulder", "x": ["Behandlungsmodell von McClure und Michener 2015: erst Reizbarkeit einstufen, dann die Intensität danach wählen.", "Laut den Autoren konzeptionell und nicht validiert."], "q": "Phys Ther 2015"}, "spadi": {"t": "SPADI", "x": ["Shoulder Pain and Disability Index: 13 Fragen zu Schmerz und Alltag, 0–100 Punkte, höher ist schlechter.", "Kleinste spürbare Besserung etwa 8–13 Punkte."], "q": "Fragebogen"}, "progressiv": {"t": "Progressives Krafttraining", "x": ["Die Last wird regelmäßig gesteigert, etwa alle zwei Wochen, sobald die Wiederholungen sauber gehen.", "In der JOSPT-Auswertung senkte es den Schmerz um gut einen Punkt auf der 10er-Skala."], "q": "JOSPT 2025"}, "holmgren": {"t": "Holmgren 2012", "x": ["102 Patienten auf der OP-Warteliste, Beschwerden über 6 Monate, alle bekamen erst eine Injektion.", "Exzentrische Übungen 3 × 15, 2× täglich bis Woche 8, dann 1× täglich bis Woche 12, Last alle 2 Wochen höher. Danach wollten nur 20 % operiert werden, in der Kontrollgruppe 63 %."], "q": "BMJ 2012"}, "ingwersen": {"t": "Ingwersen 2017", "x": ["100 Patienten, 12 Wochen schweres gegen leichtes progressives Training.", "Kein Unterschied in Funktion, Schmerz und Kraft."], "q": "OJSM 2017"}, "sad": {"t": "Subakromiale Dekompression", "x": ["Operation, bei der Knochen unter dem Schulterdach abgetragen wird.", "In CSAW und FIMPACT nach einem Jahr nicht besser als eine Schein-OP. Die BMJ-Empfehlung 2019 rät stark ab."], "q": "BMJ 2019"}}}, {"id": "w48-aha", "titel": "Schlaganfall-Reha: neue AHA-Leitlinie 2026", "art": "neu", "kb": "NE01", "min": 9, "abschnitte": [{"t": "1. Worum geht es?", "b": [{"p": ["Am 27.08.2026 haben die American Heart Association und die American Stroke Association in der Zeitschrift Stroke eine neue Leitlinie zur Rehabilitation nach Schlaganfall veröffentlicht (Richards et al.). Sie ersetzt die Fassung von 2016. Leiterin der Gruppe ist die Ergotherapeutin Lorie Gage Richards."]}, {"l": ["Neu oder überarbeitet sind vor allem Begleiterkrankungen, Frakturrisiko, Sturzvorbeugung, Unterstützung der Angehörigen, Teilhabe sowie die Rückkehr in Arbeit und ans Steuer.", "Die Telereha wird als wirksamer Weg für Behandlung zu Hause hervorgehoben.", "Für Physiotherapeuten gibt es eigene „Top Take-Home Messages“, verfasst von Alicen Whitaker-Hilbig aus der Leitliniengruppe."]}, {"fig": [{"src": "wissen/NE01.webp", "t": "Schlaganfall, Plakat aus Wissen › Krankheitsbilder.", "c": "Die Karte NE01 fasst Befund, Prognose und Behandlung zusammen. Die neue Leitlinie ergänzt sie."}]}]}, {"t": "2. Früh anfangen, aber nicht zu heftig", "b": [{"p": ["Die Reha soll im Krankenhaus beginnen, sobald der Patient medizinisch stabil ist, möglichst innerhalb von 48 Stunden. Lagewechsel und Mobilisation werden in den ersten 24–48 Stunden schrittweise gesteigert."]}, {"tab": [["Unter 24 Stunden", "keine mittel- bis hochintensiven Übungen und kein intensives Aufgabentraining"], ["Besonders vorsichtig", "schwer betroffene Patienten, Hirnblutung, eingeschränktes Bewusstsein"], ["Warum", "sehr frühe, intensive und lange Einheiten können den Kreislauf destabilisieren und das neurologische Ergebnis verschlechtern"]], "merk": "Früh heißt sanft: in den ersten 24 Stunden keine intensive Belastung, danach schrittweise mehr."}]}, {"t": "3. Gehen üben", "b": [{"l": ["Hoch dosiertes, aufgabenspezifisches Gehtraining ab der frühen subakuten Phase und weiter in der chronischen Phase verbessert das Gehen, ohne mehr schwere Zwischenfälle.", "Als Ergänzung genannt: Krafttraining, rhythmische akustische Signale, CIMT, Bewegungsvorstellung, Spiegeltherapie, Exergaming, funktionelle und sensible Elektrostimulation, Training im Wasser, Akupunktur und visuelles Biofeedback.", "Laufband mit Gewichtsentlastung und Gangroboter waren nicht besser als aufgabenspezifisches Gehtraining und sind teurer. Roboter können die Therapeuten körperlich entlasten.", "Fußheberschwäche: FES der Fußheber beim Gehen verbessert das Gehen ähnlich gut wie eine klassische Unterschenkelorthese (AFO)."], "merk": "Gehen lernt man durch Gehen, viel und gezielt. Technik ersetzt keine Wiederholungen."}]}, {"t": "4. Bewegung im Alltag und Messen", "b": [{"l": ["Ziel: mindestens 150 Minuten pro Woche moderates Ausdauertraining, dazu an 2–3 Tagen Kraft und Gleichgewicht. Die Leitlinie nennt 150–300 Minuten an 3–5 Tagen.", "Das Programm entsteht in der Reha und läuft zu Hause oder im Verein weiter. Ziele, Intensität, Häufigkeit und Dauer werden gemeinsam festgelegt.", "Im Alltag mehr stehen, gehen und Hausarbeit machen.", "Messen in der Praxis: Fugl-Meyer und ARAT für den Arm, modifizierte Ashworth-Skala für den Tonus, 10-m-Gehtest und 6-Minuten-Gehtest, Berg Balance Scale, Timed Up and Go, Functional Reach Test. Schrittzähler und Beschleunigungssensoren können den Alltag abbilden."]}]}, {"t": "5. Stürze, Knochen, Angehörige", "b": [{"l": ["Sturzrisiko so früh wie möglich einschätzen und jährlich wiederholen.", "Sturzvorbeugung: Aufklärung von Patient und Angehörigen, Wohnungsanpassung, Hilfsmittel und Orthesen, Gleichgewichtstraining wie Tai Chi, Dual-Task-Training und Exergaming. Sturzangst ansprechen, sie führt zu Inaktivität.", "Ausdauer, Kraft und Gleichgewicht können die Knochendichte verbessern und das Frakturrisiko senken.", "Bei Spastik sind Dehnprogramme sinnvoll, um Kontrakturen vorzubeugen. Überkopf-Seilzüge werden für Beweglichkeit und Schulterschmerz nicht empfohlen.", "In den USA helfen etwa 2,7 Millionen Angehörige. Sie sollen in Planung, Schulung und Unterstützung einbezogen werden.", "Ist ambulante Reha schwer erreichbar, sind Reha zu Hause und Telereha sinnvolle Alternativen."], "merk": "Sturzrisiko gleich am Anfang erfassen, Angehörige von Anfang an mitnehmen."}]}, {"t": "6. Was das für die Praxis heißt", "b": [{"l": ["Die Karte Schlaganfall (NE01) in Wissen › Krankheitsbilder passt zur neuen Leitlinie: aufgabenorientiertes Training, keine sehr frühe, hoch dosierte Mobilisation, Laufband mit Gewichtsentlastung und Gangroboter nicht besser.", "Für die Hausbesuche: Gehtraining im echten Alltag, Sturzrisiko, Wohnung und Angehörige gehören in jede Erstbefundung.", "Bewegungsziel von 150 Minuten pro Woche mit dem Patienten als realistischen Plan aufschreiben.", "Gehgeschwindigkeit im 10-m-Gehtest regelmäßig messen und dokumentieren."]}]}], "quellen": ["Richards LG et al. 2026 Guideline for Adult Stroke Rehabilitation and Recovery. Stroke 2026, doi 10.1161/STR.0000000000000536", "AHA/ASA: Top Take-Home Messages for Physical Therapists (Whitaker-Hilbig), 2026", "AHA Newsroom, 27.08.2026: Stroke rehab should start early and address physical, cognitive and mental health", "Stroke.org: Key recommendations, The Rehabilitation Program; Prevention and Medical Management of Comorbidities (2026)"], "fragen": [["Wann soll die Reha nach einem Schlaganfall laut AHA 2026 beginnen?", ["Sobald der Patient stabil ist, möglichst innerhalb von 48 Stunden", "Erst nach der Entlassung", "Frühestens nach 2 Wochen", "Sofort mit hoher Intensität in den ersten Stunden"], 0, "Die Reha beginnt im Krankenhaus, sobald der Patient medizinisch stabil ist, möglichst innerhalb von 48 Stunden."], ["Was soll in den ersten 24 Stunden nach einem Schlaganfall vermieden werden?", ["Lagewechsel", "Atemübungen", "Mittel- bis hochintensive Übungen", "Gespräch mit Angehörigen"], 2, "In den ersten 24 Stunden keine mittel- bis hochintensive Belastung. Sehr frühe, intensive Einheiten können den Kreislauf destabilisieren."], ["Bei welchen Patienten ist in der hyperakuten Phase besondere Vorsicht geboten?", ["Bei leicht Betroffenen", "Bei jungen Sportlern", "Bei Hirnblutung, schwerer Betroffenheit oder eingeschränktem Bewusstsein", "Bei Patienten mit Brille"], 2, "Die Leitlinie nennt schwer betroffene Patienten, intrazerebrale Blutung und verändertes Bewusstsein als besonders gefährdet."], ["Was sagt die Leitlinie zu Laufband mit Gewichtsentlastung und Gangroboter?", ["Beide sind dem Gehtraining klar überlegen", "Nicht besser als aufgabenspezifisches Gehtraining und teurer", "Nur Roboter sind sinnvoll", "Beide sind gefährlich"], 1, "Sie brachten keine besseren Gehergebnisse als aufgabenspezifisches Training. Roboter können aber die Therapeuten körperlich entlasten."], ["Wie schneidet FES der Fußheber im Vergleich zur Unterschenkelorthese ab?", ["Ähnlich gute Verbesserung des Gehens", "Deutlich schlechter", "Nur in der Akutphase besser", "FES wird nicht mehr empfohlen"], 0, "FES der Fußheber beim Gehen verbessert das Gehen ähnlich gut wie eine klassische AFO."], ["Welches Bewegungsziel nennt die Leitlinie?", ["30 Minuten pro Woche", "Täglich 2 Stunden Krafttraining", "Nur Gehen, kein Krafttraining", "Mindestens 150 Minuten moderates Ausdauertraining pro Woche plus 2–3 Tage Kraft und Gleichgewicht"], 3, "Mindestens 150 Minuten pro Woche moderat, dazu an 2–3 Tagen Kraft- und Gleichgewichtstraining."], ["Wann soll das Sturzrisiko erfasst werden?", ["Erst nach dem ersten Sturz", "Nur bei über 80-Jährigen", "So früh wie möglich, dann jährlich", "Nie, es ist nicht vorhersagbar"], 2, "Die Sturzrisikoeinschätzung soll so früh wie möglich erfolgen und jährlich wiederholt werden."], ["Was wird bei Schulterproblemen nach Schlaganfall ausdrücklich nicht empfohlen?", ["Lagerung", "Aufklärung", "Aktive Übungen im schmerzfreien Bereich", "Überkopf-Seilzüge"], 3, "Überkopf-Seilzüge werden nicht empfohlen, weder für die Beweglichkeit noch gegen Schulterschmerz."], ["Welche Rolle spielt die Telereha in der neuen Leitlinie?", ["Sinnvolle Alternative, wenn ambulante Reha schwer erreichbar ist", "Sie wird abgelehnt", "Sie ersetzt jede Präsenztherapie", "Sie ist nur für Sprachtherapie vorgesehen"], 0, "Wenn ambulante Reha begrenzt oder nicht erreichbar ist, sind Reha zu Hause und Telereha sinnvolle Alternativen."], ["Welche Fassung ersetzt die Leitlinie von 2026?", ["2006", "2016", "2021", "2024"], 1, "Die neue Leitlinie ersetzt die Fassung von 2016."]], "info": {}}, {"id": "w48-hue", "titel": "Koxarthrose", "art": "kb", "kb": "HU01", "min": 10, "abschnitte": [{"t": "1. Was ist das eigentlich?", "b": [{"p": ["Verschleiß des Hüftgelenks mit Knorpelverlust, Osteophyten und Kapselveränderung. Die Diagnose ist klinisch, ein Röntgenbild braucht es bei typischem Bild nicht."]}, {"l": ["17,9 % der Erwachsenen in Deutschland haben eine Arthrose, alle Gelenke zusammen (RKI GEDA).", "Weltweit 418 Hüftarthrosen je 100.000 Menschen, bis 2050 werden etwa 79 % mehr Fälle erwartet (GBD 2021).", "Risikofaktoren laut S2k-Leitlinie: Alter, Dysplasie, femoroazetabuläres Impingement, Trauma, Übergewicht, familiäre Belastung.", "Röntgenbefund und Beschwerden passen oft nicht zusammen."]}]}, {"t": "2. Typische Symptome und Verlauf", "b": [{"l": ["Leistenschmerz, oft bis zum Knie. Fast die Hälfte hat auch Schmerz unterhalb des Knies.", "Anlauf- und Belastungsschmerz, kurze Morgensteifigkeit.", "Innenrotation und Flexion sind früh eingeschränkt (Kapselmuster).", "Hinken, Schuhe und Socken anziehen fällt schwer."]}, {"bars": [["Röntgenarthrose am Anfang", 19, "CHECK-Kohorte"], ["Röntgenarthrose nach 10 Jahren", 49, "das Bild wird schlechter"], ["Noch Hüftschmerz nach 10 Jahren", 51, "Schmerz NRS im Mittel von 3,7 auf 2,9"], ["Prothese in 10 Jahren", 12, "etwa jeder Achte"]]}, {"p": ["Die Zahlen stammen aus der niederländischen CHECK-Kohorte (van Berkel 2021). Das Röntgenbild wird über Jahre meist schlechter, die Beschwerden oft nicht."], "merk": "Das Röntgenbild sagt wenig darüber, wie es dem Patienten geht."}, {"rot": "Ärztlich: Fieber und akut heißes Gelenk (septische Arthritis), plötzlicher Belastungsschmerz bei Osteoporose (Stress- oder Insuffizienzfraktur), Kortison, Alkohol oder Sichelzellerkrankung in der Vorgeschichte (Hüftkopfnekrose), Ruhe- und Nachtschmerz mit Gewichtsverlust."}]}, {"t": "3. Befund und Abgrenzung", "b": [{"l": ["Passive Innenrotation und Flexion im Seitenvergleich.", "Scour-Test, Schmerz in der Hocke, Schmerz bei aktiver Flexion und Extension.", "Gangbild, Trendelenburg, Kraft der Hüftabduktoren und -extensoren.", "LWS und Trochanter mit untersuchen."]}, {"p": ["[[ACR-Kriterien|acr]]: Hüftschmerz plus Innenrotation unter 15° und weitere Merkmale, klinisch Sensitivität 86 %, Spezifität 75 %. Im [[Sutlive-Cluster|sutlive]] machen 4 von 5 positiven Zeichen eine Arthrose sehr wahrscheinlich (LR+ 24,3, aber mit sehr breitem Konfidenzintervall und nicht validiert)."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hue-trendelenburg.webp", "t": "Einbeinstand rechts, Ansicht von hinten.", "c": "Links normal: Der rechte Gluteus medius hält das Becken waagerecht. Rechts Trendelenburg-Zeichen: Der Muskel ist schwach, das Becken sinkt zur Seite des angehobenen Beins ab."}]}, {"tab": [["Gluteale Tendinopathie", "Schmerz seitlich am Trochanter, Liegen auf der Seite"], ["Lumbale Radikulopathie", "Dermatom, Neurologie, LWS-Bewegung provoziert"], ["FAI, Labrum", "jünger, Leiste, Blockaden"], ["Hüftkopfnekrose", "Kortison, Alkohol, rascher Verlauf. MRT, ärztlich"], ["Leistenhernie, Bauch", "Husten, Pressen, Bauchsymptome"]]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."]}]}, {"t": "4. Messen", "b": [{"tab": [["Timed Up and Go", "spürbar 0,8–1,4 s schneller"], ["40-m-Gehtest", "0,2–0,3 m/s schneller"], ["30-s-Chair-Stand", "2–2,6 Wiederholungen mehr"], ["20-cm-Stufentest", "5–16 Stufen mehr"]], "p": ["Die Schwellen stammen aus Wright 2011. Für HOOS, WOMAC und NPRS ließ sich bei Hüftarthrose kein MCID belegen."]}]}, {"t": "5. Was hilft laut Studienlage?", "b": [{"p": ["Die S2k-Leitlinie Koxarthrose von 2019 ist abgelaufen und in Überarbeitung, die S3-Leitlinie zur Hüftprothese ([[EKIT-Hüfte|ekit]]) seit 03/2026 ebenfalls. Einig sind sich alle Leitlinien (NICE, EULAR, JOSPT, ACR, OARSI): Schulung, Bewegungstherapie und bei Übergewicht Abnehmen zuerst."]}, {"l": ["Übungstherapie ist überall erste Wahl, kein Übungstyp ist überlegen.", "Der Effekt ist eher klein: Schmerz etwa 7 von 100 Punkten besser als keine Behandlung, spürbar wären etwa 12 ([[Cochrane 2026|cochrane]]).", "GLA:D Hüfte: Schmerz nach 3 Monaten 11 von 100 Punkten besser, allerdings Registerdaten ohne Kontrollgruppe.", "Kraft für Hüftabduktoren und -extensoren, Sit-to-Stand, 3 × 10–12, steigend. Ausdauer 15–30 min auf dem Ergometer, beim Gehen oder im Wasser.", "Manuelle Therapie: Hoeksma 2004 positiv, in der Studie mit Scheinbehandlung (Bennell 2014) kein Zusatznutzen und mehr Nebenwirkungen. Nur zusammen mit Übungen.", "Prähabilitation vor der TEP verbessert die Leistungstests nach der OP, kaum den Schmerz."]}, {"tab": [["Nicht empfohlen", "TENS, Ultraschall, Elektrotherapie, Hyaluronsäure"], ["TEP-Indikation (EKIT)", "Kellgren-Lawrence 3 oder 4, hoher Leidensdruck trotz mindestens 3 Monaten konservativer Therapie, andere Ursachen ausgeschlossen"]], "merk": "Schmerz beim Training bis 5 von 10 ist erlaubt, wenn er am nächsten Morgen zurück auf dem gewohnten Niveau ist (Expertenmeinung)."}]}, {"t": "6. Für den Praxisalltag", "b": [{"l": ["Schulung in jeder Einheit: Bewegung schützt das Gelenk, Schmerz heißt nicht Schaden.", "Am Anfang 30-s-Chair-Stand und TUG messen, nach 6 Wochen wiederholen.", "Programm 6–12 Wochen, 2× pro Woche plus Heimprogramm.", "Nach einer Kortisonspritze mindestens 6 Wochen, besser 3 Monate bis zur OP.", "Vor der TEP Gehhilfen üben und den Ablauf nach der OP erklären."], "merk": "Fürs Patientengespräch: „Das Röntgenbild sagt wenig darüber, wie es Ihnen geht. Training für Kraft und Ausdauer ist die wichtigste Behandlung, und ein bisschen Schmerz beim Üben ist erlaubt.“"}]}], "quellen": ["S2k Koxarthrose, AWMF 033-001, 2019, abgelaufen, in Überarbeitung", "S3 EKIT-Hüfte, AWMF 187-001, 2021, gültig bis 23.03.2026, in Überarbeitung", "NICE NG226 2022; EULAR 2024; JOSPT CPG Hip OA Revision 2025; ACR 2019; OARSI 2019", "Cochrane 2026 (Übungen bei Hüftarthrose, CD007912.pub3); Skou & Roos 2017 (GLA:D)", "Hoeksma 2004; Bennell JAMA 2014; Altman 1991; Sutlive 2008; van Berkel 2021 (CHECK); Wright JOSPT 2011; GBD 2021; RKI GEDA"], "fragen": [["Welche Bewegung ist bei Koxarthrose typischerweise zuerst eingeschränkt?", ["Extension", "Adduktion", "Außenrotation", "Innenrotation"], 3, "Das Kapselmuster der Hüfte: Innenrotation vor Flexion vor Abduktion."], ["Was gehört zu den klinischen ACR-Kriterien?", ["Leistenschmerz nur beim Husten", "Positiver Lasègue", "Innenrotation unter 15°", "Alter unter 30"], 2, "Hüftschmerz plus Innenrotation unter 15° und weitere Merkmale wie Alter über 50 und Morgensteifigkeit."], ["Braucht es bei typischem klinischem Bild ein Röntgen für die Diagnose?", ["Ja, immer", "Nur ein MRT", "Nur bei Männern", "Nein, die Diagnose ist klinisch"], 3, "Die Diagnose ist klinisch. Röntgen braucht es bei atypischem Bild oder vor einer OP."], ["Was zeigt das rechte Bild?", ["Duchenne-Hinken bei Spastik", "Trendelenburg-Zeichen bei schwachem Gluteus medius", "Beinlängendifferenz", "Normaler Einbeinstand"], 1, "Das Becken sinkt zur Seite des angehobenen Beins. Schwach ist der Gluteus medius des Standbeins.", "fortbildung/bilder/2026-W47/ana-hue-trendelenburg.webp"], ["Wie groß ist der Effekt von Übungen auf den Schmerz laut Cochrane 2026 etwa?", ["Etwa 50 von 100 Punkten", "Gar keiner", "Etwa 7 von 100 Punkten", "Etwa 30 von 100 Punkten"], 2, "Etwa 7 von 100 Punkten besser als keine Behandlung. Spürbar wären etwa 12."], ["Was gilt im 30-s-Chair-Stand als spürbare Besserung?", ["Eine halbe Wiederholung", "Mindestens 10 Wiederholungen mehr", "Nur die Zeit zählt", "Etwa 2–2,6 Wiederholungen mehr"], 3, "Nach Wright 2011 sind 2–2,6 Wiederholungen mehr spürbar."], ["Was zeigte Bennell 2014 zur manuellen Therapie bei Hüftarthrose?", ["Großer Zusatznutzen", "Kein Zusatznutzen gegenüber Scheinbehandlung, mehr Nebenwirkungen", "Nur Traktion hilft", "Besser als jede Übung"], 1, "In der Studie mit Scheinbehandlung brachte die aktive Physiotherapie mit manueller Therapie keinen Zusatznutzen."], ["Wann ist laut EKIT-Hüfte eine Prothese angezeigt?", ["Bei jedem Leistenschmerz", "Sobald das Röntgen einen Osteophyten zeigt", "Bei Kellgren-Lawrence 3–4, hohem Leidensdruck und mindestens 3 Monaten konservativer Therapie", "Nur unter 50 Jahren"], 2, "Strukturschaden 3–4, hoher Leidensdruck trotz mindestens 3 Monaten leitliniengerechter konservativer Therapie und andere Ursachen ausgeschlossen."], ["Wie viele bekamen in der CHECK-Kohorte in 10 Jahren eine Hüft-TEP?", ["Etwa 50 %", "Etwa 12 %", "Fast alle", "Niemand"], 1, "Etwa jeder Achte, 12 %. Das Röntgenbild wurde schlechter, der Schmerz blieb im Mittel stabil."], ["Welche Maßnahme wird bei Hüftarthrose nicht empfohlen?", ["TENS", "Schulung", "Krafttraining", "Abnehmen bei Übergewicht"], 0, "TENS, Ultraschall, Elektrotherapie und Hyaluronsäure werden nicht empfohlen."], ["Was ist ein Warnzeichen, das ärztlich abgeklärt werden muss?", ["Fieber mit akut heißem Hüftgelenk", "Anlaufschmerz am Morgen", "Schmerz beim Socken anziehen", "Leichtes Hinken nach langem Gehen"], 0, "Fieber und akut heißes Gelenk können eine septische Arthritis sein."], ["Wie lange sollte nach einer Kortisonspritze bis zur Hüft-TEP mindestens vergehen?", ["Mindestens 6 Wochen, besser 3 Monate", "1 Tag", "1 Jahr", "Gar keine Pause"], 0, "Zwischen Kortisonspritze und OP mindestens 6 Wochen, besser 3 Monate."]], "info": {"acr": {"t": "ACR-Kriterien (Altman 1991)", "x": ["Klinische Kriterien der Hüftarthrose: Hüftschmerz plus Innenrotation unter 15° und weitere Merkmale (Alter über 50, Morgensteifigkeit, Schmerz bei Innenrotation).", "Klinisch Sensitivität 86 %, Spezifität 75 %; mit Röntgen 89 % und 91 %."], "q": "Altman 1991"}, "sutlive": {"t": "Sutlive-Cluster", "x": ["5 Zeichen: Scour-Test, passive Innenrotation höchstens 25°, Schmerz in der Hocke, Schmerz bei aktiver Flexion, Schmerz bei aktiver Extension.", "4 von 5 positiv: LR+ 24,3 (KI 4,4–142,1); 3 von 5: LR+ 5,2, LR− 0,33. Kleine Studie, nicht validiert."], "q": "Sutlive 2008"}, "ekit": {"t": "EKIT-Hüfte", "x": ["S3-Leitlinie zur Indikation der Hüft-TEP, AWMF 187-001, 2021, seit 03/2026 abgelaufen, in Überarbeitung.", "TEP bei Kellgren-Lawrence 3–4, hohem Leidensdruck und mindestens 3 Monaten erfolgloser konservativer Therapie."], "q": "AWMF 187-001"}, "cochrane": {"t": "Cochrane 2026", "x": ["Update zu Übungen bei Hüftarthrose: 18 Studien, 1368 Teilnehmende.", "Schmerz etwa 7 von 100 Punkten besser als keine Behandlung, gegen Schein-Behandlung noch weniger."], "q": "CD007912.pub3"}}}], "anatomie": [{"id": "w48-ana-ell", "titel": "Ellenbogengelenk", "art": "ana", "min": 11, "abschnitte": [{"t": "1. Aufbau im Überblick", "b": [{"p": ["Der Ellenbogen ist ein zusammengesetztes Gelenk aus drei Teilgelenken in einer gemeinsamen Kapsel. Er beugt und streckt den Arm und dreht zusammen mit dem distalen Radioulnargelenk den Unterarm."]}, {"tab": [["Humeroulnargelenk", "Trochlea humeri in der Incisura trochlearis der Ulna. Scharniergelenk, führt Flexion und Extension und gibt die knöcherne Stabilität"], ["Humeroradialgelenk", "Capitulum humeri mit dem Radiuskopf. Macht Beugung, Streckung und Drehung mit"], ["Proximales Radioulnargelenk", "Radiuskopf in der Incisura radialis der Ulna, gehalten vom Lig. anulare. Zusammen mit dem distalen Radioulnargelenk für Pronation und Supination"], ["Epikondylen", "Medial Ursprung der Flexoren und Pronatoren, lateral Ursprung der Extensoren und Supinatoren"], ["Tragwinkel", "In Streckung und Supination steht der Unterarm etwa 10–15° nach außen (Cubitus valgus physiologicus), bei Frauen etwas mehr"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-ell-knochen.webp", "t": "Rechter Ellenbogen von vorne, Kapsel entfernt.", "c": "1 Humeroulnargelenk, 2 Humeroradialgelenk, 3 proximales Radioulnargelenk, 4 Lig. anulare radii, 5 Epicondylus medialis, 6 Epicondylus lateralis. Lateral liegt im Bild links."}]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."], "merk": "Drei Gelenke, eine Kapsel. Wer die Pro- und Supination prüft, prüft immer auch das Handgelenk mit, weil das distale Radioulnargelenk beteiligt ist."}]}, {"t": "2. Bänder", "b": [{"tab": [["Lig. collaterale ulnare (mediales Kollateralband)", "Vom Epicondylus medialis zur Ulna. Das vordere Bündel ist der wichtigste Stabilisator gegen Valgusstress, etwa zwischen 30° und 120° Beugung. Typisch belastet bei Wurfsportlern"], ["Lig. collaterale radiale", "Vom Epicondylus lateralis in das Lig. anulare"], ["Lig. collaterale ulnare laterale (LUCL)", "Vom Epicondylus lateralis zur Crista m. supinatoris der Ulna. Hält gegen posterolaterale Rotationsinstabilität"], ["Lig. anulare radii", "Ring um den Radiuskopf, an der Ulna befestigt. Bei Kleinkindern kann der Radiuskopf darunter herausrutschen (Chassaignac, nursemaid's elbow)"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-ell-baender.webp", "t": "Rechter Ellenbogen, links von medial, rechts von lateral.", "c": "1 vorderes Bündel des Lig. collaterale ulnare, 2 hinteres Bündel, 3 Epicondylus medialis, 4 Lig. collaterale radiale, 5 Lig. anulare radii, 6 Lig. collaterale ulnare laterale (LUCL)."}]}, {"merk": "Medial schützt das vordere Bündel des ulnaren Kollateralbands gegen Valgus. Lateral hält das LUCL gegen die posterolaterale Instabilität, die nach Luxationen bleibt."}]}, {"t": "3. Muskeln", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W48/ana-ell-lateral.webp", "t": "Rechter Unterarm von lateral, oberflächliche Schicht.", "c": "1 M. extensor carpi radialis brevis mit Ursprung am Epicondylus lateralis, 2 M. extensor carpi radialis longus, 3 M. brachioradialis, 4 M. extensor digitorum, 5 Epicondylus lateralis. Der Ellenbogen liegt im Bild links."}]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-ell-medial.webp", "t": "Rechter Unterarm von vorne-medial, oberflächliche Schicht.", "c": "1 M. pronator teres, 2 M. flexor carpi radialis, 3 M. palmaris longus, 4 M. flexor carpi ulnaris, 5 Epicondylus medialis mit gemeinsamem Flexorenursprung. Der Ellenbogen liegt im Bild links."}]}, {"mus": [{"n": "M. biceps brachii", "u": "Caput longum: Tuberculum supraglenoidale; Caput breve: Proc. coracoideus", "a": "Tuberositas radii und über die Aponeurose an der Unterarmfaszie", "i": "N. musculocutaneus (C5–C6)", "f": "Stärkster Supinator bei gebeugtem Ellenbogen, beugt den Ellenbogen"}, {"n": "M. brachialis", "u": "Vordere Fläche des distalen Humerus", "a": "Tuberositas ulnae", "i": "N. musculocutaneus (C5–C6)", "f": "Reiner Beuger, in jeder Unterarmstellung"}, {"n": "M. brachioradialis", "z": "3", "u": "Laterale Kante des distalen Humerus", "a": "Proc. styloideus radii", "i": "N. radialis (C5–C6)", "f": "Beugt den Ellenbogen am stärksten in Mittelstellung zwischen Pro- und Supination"}, {"n": "M. triceps brachii", "u": "Caput longum: Tuberculum infraglenoidale; Caput laterale und mediale: Humerusschaft", "a": "Olecranon", "i": "N. radialis (C6–C8)", "f": "Einziger Strecker des Ellenbogens von Bedeutung"}, {"n": "M. extensor carpi radialis brevis", "z": "1", "u": "Epicondylus lateralis (gemeinsamer Extensorenursprung)", "a": "Basis des 3. Mittelhandknochens", "i": "R. profundus des N. radialis", "f": "Streckt das Handgelenk und stabilisiert es beim Greifen. Seine Ursprungssehne ist beim Tennisellenbogen meist betroffen"}, {"n": "M. pronator teres", "z": "1", "b": "ana-ell-medial.webp", "u": "Epicondylus medialis und Proc. coronoideus ulnae", "a": "Mitte des Radiusschafts lateral", "i": "N. medianus (C6–C7)", "f": "Proniert den Unterarm, hilft beim Beugen"}, {"n": "M. supinator", "u": "Epicondylus lateralis, Lig. collaterale radiale, Ulna", "a": "Proximaler Radius", "i": "R. profundus des N. radialis, der ihn durchquert", "f": "Supiniert bei gestrecktem Ellenbogen"}]}, {"merk": "Bei gestrecktem Ellenbogen supiniert vor allem der Supinator, bei gebeugtem der Bizeps. Der Brachioradialis beugt am besten in Neutralstellung."}]}, {"t": "4. Biomechanik", "b": [{"l": ["Flexion/Extension etwa 140–150/0/0–10°. Pronation und Supination je etwa 80–90° aus der Neutralstellung.", "Für den Alltag reichen ungefähr 30–130° Flexion und je 50° Pro- und Supination (funktioneller Bogen).", "In Streckung sichern Olecranon in der Fossa olecrani und die Bänder, in Beugung vor allem Muskeln und das mediale Kollateralband.", "Kapselmuster: Flexion stärker eingeschränkt als Extension. Nach Verletzung oder Ruhigstellung geht vor allem die Streckung schnell verloren.", "Beim Greifen und Heben wirken große Kräfte über die Extensorensehnen auf den lateralen Epicondylus. Darum entsteht dort die häufigste Sehnenreizung des Arms."]}, {"merk": "Steif wird der Ellenbogen schnell. Nach Trauma früh und schmerzarm bewegen, wenn die ärztliche Freigabe da ist."}]}, {"t": "5. Nerven und Gefäße", "b": [{"tab": [["N. ulnaris", "Läuft hinter dem Epicondylus medialis im Sulcus n. ulnaris (Kubitaltunnel). Häufigste Engstelle am Ellenbogen. Kribbeln im Ring- und Kleinfinger, später Schwäche der kleinen Handmuskeln"], ["N. radialis", "Teilt sich vor dem lateralen Epicondylus. Der R. profundus zieht unter der Frohse-Arkade durch den Supinator. Dort kann er eingeklemmt werden (Supinatorsyndrom), die Schmerzen ähneln dem Tennisellenbogen"], ["N. medianus", "Zieht zwischen den beiden Köpfen des Pronator teres. Selten eingeengt (Pronator-teres-Syndrom)"], ["A. brachialis", "In der Ellenbeuge medial der Bizepssehne, teilt sich in A. radialis und A. ulnaris. Bei suprakondylären Frakturen bei Kindern gefährdet"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-ell-nerven.webp", "t": "Rechter Ellenbogen, Nerven gelb, links von hinten-medial, rechts von vorne-lateral.", "c": "1 N. ulnaris im Sulcus hinter dem Epicondylus medialis, 2 Epicondylus medialis, 3 Olecranon, 4 Aufteilung des N. radialis, 5 R. profundus des N. radialis unter der Frohse-Arkade, 6 N. medianus zwischen den Köpfen des Pronator teres."}]}, {"merk": "Langes Beugen des Ellenbogens, etwa beim Telefonieren oder Schlafen, dehnt und drückt den N. ulnaris. Das erklärt nächtliches Kribbeln im Klein- und Ringfinger."}]}, {"t": "6. Klinische Bezüge", "b": [{"l": ["Laterale Epikondylopathie (Tennisellenbogen): Sehnenreizung am Ursprung des Extensor carpi radialis brevis. Schmerz beim Greifen und bei Handgelenksstreckung gegen Widerstand. Meist gute Prognose, belastungsdosiertes Training.", "Mediale Epikondylopathie (Golferellenbogen): gleiche Idee am Ursprung der Flexoren und Pronatoren.", "Kubitaltunnelsyndrom: zweithäufigstes Nervenkompressionssyndrom am Arm nach dem Karpaltunnelsyndrom.", "Radiuskopffraktur: häufigste Fraktur am Ellenbogen bei Erwachsenen, typisch nach Sturz auf die ausgestreckte Hand.", "Ellenbogenluxation: meist nach hinten. Danach auf posterolaterale Instabilität und Bewegungsverlust achten."]}, {"merk": "Schmerz am lateralen Epicondylus plus Kribbeln oder Schmerz weiter distal im Unterarm: auch an den R. profundus des N. radialis denken."}]}], "quellen": ["Schünke M, Schulte E, Schumacher U. Prometheus LernAtlas Allgemeine Anatomie und Bewegungssystem", "Kapandji IA. Funktionelle Anatomie der Gelenke, Band 1", "Morrey BF et al. A biomechanical study of normal functional elbow motion. J Bone Joint Surg Am 1981"], "fragen": [["Welches Teilgelenk ist mit der 2 markiert?", ["Humeroulnargelenk", "Proximales Radioulnargelenk", "Distales Radioulnargelenk", "Humeroradialgelenk"], 3, "Die 2 zeigt das Capitulum humeri mit dem Radiuskopf, also das Humeroradialgelenk.", "fortbildung/bilder/2026-W48/ana-ell-knochen.webp"], ["Welche Struktur hält den Radiuskopf an der Ulna?", ["Lig. collaterale radiale", "Lig. anulare radii", "Membrana interossea", "Lig. collaterale ulnare"], 1, "Das Lig. anulare umfasst den Radiuskopf ringförmig und ist an der Ulna befestigt."], ["Welcher Teil des medialen Kollateralbands ist der wichtigste Stabilisator gegen Valgusstress?", ["Vorderes Bündel", "Hinteres Bündel", "Querbündel", "Lig. anulare"], 0, "Das vordere Bündel stabilisiert vor allem zwischen 30° und 120° Beugung, typisch belastet beim Werfen."], ["Welcher Muskel ist mit der 1 markiert?", ["M. extensor carpi radialis brevis", "M. extensor digitorum", "M. brachioradialis", "M. extensor carpi ulnaris"], 0, "Die 1 ist der Extensor carpi radialis brevis. Seine Ursprungssehne ist beim Tennisellenbogen meist betroffen.", "fortbildung/bilder/2026-W48/ana-ell-lateral.webp"], ["Welcher Muskel ist der stärkste Supinator bei gebeugtem Ellenbogen?", ["M. supinator", "M. brachioradialis", "M. biceps brachii", "M. brachialis"], 2, "Bei gebeugtem Ellenbogen supiniert vor allem der Bizeps, bei gestrecktem der Supinator."], ["Wie groß ist der physiologische Tragwinkel ungefähr?", ["0°", "Etwa 10–15° nach außen", "Etwa 30° nach innen", "Etwa 40° nach außen"], 1, "In Streckung und Supination steht der Unterarm etwa 10–15° nach außen, bei Frauen etwas mehr."], ["Welcher Nerv läuft hinter dem Epicondylus medialis?", ["N. medianus", "N. radialis", "N. ulnaris", "N. musculocutaneus"], 2, "Der N. ulnaris liegt im Sulcus hinter dem medialen Epicondylus, im Kubitaltunnel."], ["Wo kann der R. profundus des N. radialis eingeklemmt werden?", ["Im Karpaltunnel", "Zwischen den Köpfen des Pronator teres", "Unter der Frohse-Arkade am Supinator", "Im Sulcus n. ulnaris"], 2, "Er zieht unter der Frohse-Arkade durch den Supinator. Das Supinatorsyndrom ähnelt dem Tennisellenbogen.", "fortbildung/bilder/2026-W48/ana-ell-nerven.webp"], ["Welcher Bewegungsumfang reicht ungefähr für den Alltag?", ["0–60° Flexion", "Nur volle Streckung", "90–150° Flexion", "30–130° Flexion und je 50° Pro- und Supination"], 3, "Der funktionelle Bogen nach Morrey liegt bei etwa 30–130° Flexion und je 50° Rotation."], ["Was ist die häufigste Fraktur am Ellenbogen bei Erwachsenen?", ["Olecranonfraktur", "Suprakondyläre Fraktur", "Coronoidfraktur", "Radiuskopffraktur"], 3, "Typisch nach Sturz auf die ausgestreckte Hand."], ["Welches Band hält gegen posterolaterale Rotationsinstabilität?", ["Lig. collaterale ulnare laterale (LUCL)", "Lig. anulare", "Vorderes Bündel medial", "Lig. quadratum"], 0, "Das LUCL zieht vom lateralen Epicondylus zur Ulna und hält gegen diese Instabilität."]], "info": {}}, {"id": "w48-ana-hand", "titel": "Handgelenk und Hand", "art": "ana", "min": 12, "abschnitte": [{"t": "1. Aufbau im Überblick", "b": [{"p": ["Das Handgelenk besteht aus dem proximalen Handgelenk (Radius mit Scaphoid, Lunatum und Triquetrum) und dem distalen Handgelenk zwischen den beiden Reihen der Handwurzel. Die Ulna hat keinen direkten Kontakt zur Handwurzel, dazwischen liegt der Discus des TFCC."]}, {"tab": [["Proximale Reihe", "Scaphoid, Lunatum, Triquetrum, Pisiforme. Ein Merksatz: „Schiffchen fährt im Mondschein um das Dreieck, Erbsen …“"], ["Distale Reihe", "Trapezium, Trapezoideum, Capitatum, Hamatum"], ["Scaphoid", "Brücke zwischen beiden Reihen. Wird bei Sturz auf die gestreckte Hand am häufigsten gebrochen. Die Blutversorgung kommt von distal, daher Gefahr der Nekrose des proximalen Pols"], ["Lunatum", "Liegt zentral im Radius. Häufigster luxierter Handwurzelknochen"], ["Distales Radioulnargelenk", "Zusammen mit dem proximalen für Pro- und Supination, stabilisiert durch den TFCC"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-hand-knochen.webp", "t": "Rechte Hand und Handgelenk von dorsal.", "c": "1 Os scaphoideum, 2 Os lunatum, 3 Os triquetrum, 4 Os trapezium, 5 Os trapezoideum, 6 Os capitatum, 7 Os hamatum, 8 distaler Radius. Der Daumen liegt im Bild links."}]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."], "merk": "Druckschmerz in der Tabatière nach Sturz auf die Hand: an eine Scaphoidfraktur denken, auch wenn das erste Röntgen unauffällig ist."}]}, {"t": "2. Karpaltunnel und Guyon-Loge", "b": [{"tab": [["Karpaltunnel", "Knöcherne Rinne der Handwurzel, überdacht vom Retinaculum flexorum. Darin der N. medianus und neun Sehnen: 4 × FDS, 4 × FDP, 1 × FPL"], ["N. medianus", "Liegt direkt unter dem Retinaculum, am oberflächlichsten im Tunnel, daher bei Enge zuerst betroffen"], ["Guyon-Loge", "Ulnar vom Karpaltunnel zwischen Pisiforme und Hamulus ossis hamati, mit N. ulnaris und A. ulnaris. Liegt außerhalb des Karpaltunnels"], ["Thenarast", "Motorischer Ast des N. medianus zu den Daumenballenmuskeln, zweigt oft am Ende des Tunnels ab"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-hand-karpaltunnel.webp", "t": "Querschnitt durch den rechten Karpaltunnel, Blick von distal, palmar oben.", "c": "1 Retinaculum flexorum, 2 N. medianus, 3 Sehne des M. flexor pollicis longus, 4 Sehnen der Fingerbeuger (FDS und FDP), 5 Guyon-Loge mit N. ulnaris und A. ulnaris, 6 Hamulus ossis hamati. Der Daumen liegt im Bild links."}]}, {"merk": "Neun Sehnen und ein Nerv teilen sich den Karpaltunnel. Der N. ulnaris gehört nicht dazu."}]}, {"t": "3. Sehnenfächer und Muskeln", "b": [{"tab": [["1. Strecksehnenfach", "M. abductor pollicis longus und M. extensor pollicis brevis über dem Proc. styloideus radii. Hier entsteht die Tendovaginitis de Quervain"], ["Tabatière (Fovea radialis)", "Grube zwischen 1. und 3. Fach, im Boden das Scaphoid"], ["3. Strecksehnenfach", "M. extensor pollicis longus, läuft um das Tuberculum von Lister. Kann nach distaler Radiusfraktur reißen"], ["6. Strecksehnenfach", "M. extensor carpi ulnaris in seiner Rinne an der Ulna"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-hand-dorsal.webp", "t": "Rechtes Handgelenk von dorsal-radial.", "c": "1 erstes Strecksehnenfach mit APL und EPB über dem Proc. styloideus radii, 2 Tabatière mit dem Scaphoid im Boden, 3 Sehne des EPL um das Tuberculum von Lister, 4 Retinaculum extensorum, 5 Proc. styloideus radii."}]}, {"mus": [{"n": "M. abductor pollicis brevis", "u": "Retinaculum flexorum, Scaphoid, Trapezium", "a": "Radiale Basis der Daumengrundphalanx", "i": "N. medianus (Thenarast)", "f": "Spreizt den Daumen nach palmar. Atrophiert früh beim Karpaltunnelsyndrom"}, {"n": "M. opponens pollicis", "u": "Retinaculum flexorum, Trapezium", "a": "Radialer Rand des 1. Mittelhandknochens", "i": "N. medianus", "f": "Stellt den Daumen gegenüber (Opposition)"}, {"n": "M. flexor carpi ulnaris", "u": "Epicondylus medialis und Olecranon", "a": "Pisiforme, über Bänder an Hamatum und 5. Mittelhand", "i": "N. ulnaris", "f": "Beugt das Handgelenk und neigt es nach ulnar"}, {"n": "M. extensor carpi radialis longus und brevis", "u": "Laterale Humeruskante und Epicondylus lateralis", "a": "Basis des 2. bzw. 3. Mittelhandknochens", "i": "N. radialis", "f": "Strecken das Handgelenk und halten es beim Faustschluss in leichter Extension"}, {"n": "M. interossei", "u": "Zwischen den Mittelhandknochen", "a": "Grundglieder und Streckapparat", "i": "N. ulnaris (R. profundus)", "f": "Spreizen und schließen die Finger, beugen die Grundgelenke und strecken die Mittel- und Endgelenke"}]}, {"merk": "Finkelstein-Test positiv und Druckschmerz über dem Proc. styloideus radii: an de Quervain im ersten Strecksehnenfach denken."}]}, {"t": "4. Ulnare Seite und Bänder", "b": [{"tab": [["TFCC", "Discus und Bänder zwischen Ulnakopf und Handwurzel. Puffer und wichtigster Stabilisator des distalen Radioulnargelenks"], ["Lig. scapholunatum", "Wichtigstes Band der proximalen Reihe. Reißt es, kippt das Scaphoid und es entsteht eine Lücke zwischen Scaphoid und Lunatum"], ["ECU-Sehne", "Liegt in einer eigenen Rinne an der Ulna. Springt sie bei Supination heraus, schmerzt es ulnar"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-hand-ulnar.webp", "t": "Rechtes Handgelenk von dorsal, ulnare Seite, tiefe Schicht.", "c": "1 TFCC, 2 Caput ulnae, 3 Sehne des M. extensor carpi ulnaris, 4 Lig. scapholunatum, 5 distales Radioulnargelenk. Der Kleinfinger liegt im Bild rechts."}]}, {"merk": "Ulnarer Handgelenksschmerz bei Belastung mit Pro- und Supination: an den TFCC denken."}]}, {"t": "5. Daumen und Biomechanik", "b": [{"l": ["Das Daumensattelgelenk (CMC 1) zwischen Trapezium und 1. Mittelhandknochen erlaubt Abduktion, Adduktion, Flexion, Extension und die Opposition. Es ist eine häufige Arthrosestelle (Rhizarthrose), vor allem bei Frauen nach 50.", "Das ulnare Kollateralband am Daumengrundgelenk reißt beim Skidaumen. Bei kompletter Ruptur kann sich die Adduktoraponeurose dazwischenlegen (Stener-Läsion), dann heilt es nicht von allein.", "Handgelenk: Extension etwa 70°, Flexion etwa 80°, Radialabduktion etwa 20°, Ulnarabduktion etwa 30–40°.", "Die Funktionsstellung für Greifen liegt bei etwa 20–30° Extension und leichter Ulnarabduktion. Darin ist der Faustschluss am kräftigsten.", "Die Extension entsteht vor allem im Mediokarpalgelenk, die Flexion stärker im Radiokarpalgelenk."]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-hand-daumen.webp", "t": "Rechter Daumen von palmar-radial.", "c": "1 Os trapezium, 2 Daumensattelgelenk (CMC 1), 3 M. abductor pollicis brevis, 4 M. opponens pollicis, 5 ulnares Kollateralband des Daumengrundgelenks."}]}, {"merk": "Kraftvolles Greifen braucht ein leicht gestrecktes Handgelenk. Deshalb schmerzt der Tennisellenbogen beim Greifen."}]}, {"t": "6. Klinische Bezüge", "b": [{"l": ["Distale Radiusfraktur: häufigste Fraktur des Erwachsenen, meist Sturz auf die gestreckte Hand (Colles-Typ mit Abkippung nach dorsal).", "Scaphoidfraktur: Druckschmerz in der Tabatière. Ist das erste Röntgen negativ, trotzdem ruhigstellen und weiter abklären.", "Karpaltunnelsyndrom: nächtliches Kribbeln in Daumen bis Mittelfinger. Später Atrophie des Daumenballens.", "Tendovaginitis de Quervain: Schmerz über dem Proc. styloideus radii, Finkelstein-Test.", "Rhizarthrose: Schmerz an der Daumenbasis beim Drehen und Kneifen."]}, {"merk": "Taubheit im Kleinfinger ohne Ellenbogenbezug, aber mit Druck auf die Handkante (Radfahrer): an die Guyon-Loge denken."}]}], "quellen": ["Schünke M, Schulte E, Schumacher U. Prometheus LernAtlas Allgemeine Anatomie und Bewegungssystem", "Kapandji IA. Funktionelle Anatomie der Gelenke, Band 1", "Palmer AK, Werner FW. The triangular fibrocartilage complex of the wrist. J Hand Surg 1981"], "fragen": [["Welcher Knochen ist mit der 1 markiert?", ["Lunatum", "Trapezium", "Scaphoid", "Capitatum"], 2, "Die 1 ist das Scaphoid, die Brücke zwischen den beiden Handwurzelreihen.", "fortbildung/bilder/2026-W48/ana-hand-knochen.webp"], ["Warum ist der proximale Pol des Scaphoids nach einer Fraktur gefährdet?", ["Die Blutversorgung kommt von distal", "Er hat keine Bänder", "Er liegt im Karpaltunnel", "Er wird vom N. ulnaris versorgt"], 0, "Die Gefäße treten distal ein. Bricht der Knochen, kann der proximale Pol absterben."], ["Was liegt NICHT im Karpaltunnel?", ["N. medianus", "Sehne des M. flexor pollicis longus", "Sehnen des M. flexor digitorum profundus", "N. ulnaris"], 3, "Der N. ulnaris liegt in der Guyon-Loge, außerhalb des Karpaltunnels."], ["Was ist im Querschnitt mit der 2 markiert?", ["N. medianus", "N. ulnaris", "Sehne des FPL", "Retinaculum flexorum"], 0, "Der N. medianus liegt direkt unter dem Retinaculum flexorum.", "fortbildung/bilder/2026-W48/ana-hand-karpaltunnel.webp"], ["Welche Sehnen laufen im ersten Strecksehnenfach?", ["EPL und ECU", "ECRL und ECRB", "APL und EPB", "EDC und EIP"], 2, "Abductor pollicis longus und Extensor pollicis brevis. Hier entsteht die Tendovaginitis de Quervain."], ["Was ist am Handrücken mit der 2 markiert?", ["Tuberculum von Lister", "Erstes Strecksehnenfach", "Tabatière mit dem Scaphoid im Boden", "Proc. styloideus ulnae"], 2, "Die Tabatière liegt zwischen erstem und drittem Fach, darunter das Scaphoid.", "fortbildung/bilder/2026-W48/ana-hand-dorsal.webp"], ["Welche Struktur stabilisiert vor allem das distale Radioulnargelenk?", ["Lig. scapholunatum", "Retinaculum flexorum", "Lig. anulare", "TFCC"], 3, "Der TFCC ist der wichtigste Stabilisator des distalen Radioulnargelenks."], ["Was passiert typischerweise bei einer Ruptur des Lig. scapholunatum?", ["Das Lunatum bricht", "Lücke zwischen Scaphoid und Lunatum, das Scaphoid kippt", "Der N. medianus wird eingeklemmt", "Die Daumenbasis luxiert"], 1, "Ohne das Band kippt das Scaphoid und der Spalt zwischen Scaphoid und Lunatum wird weiter."], ["Was ist eine Stener-Läsion?", ["Adduktoraponeurose liegt zwischen den Enden des gerissenen ulnaren Kollateralbands am Daumen", "Bruch des Hamulus", "Riss der EPL-Sehne", "Engpass in der Guyon-Loge"], 0, "Dann heilt das Band nicht von allein, meist ist eine OP nötig."], ["In welcher Handgelenksstellung ist der Faustschluss am kräftigsten?", ["30° Flexion", "Maximale Flexion", "Maximale Radialabduktion", "Etwa 20–30° Extension und leichte Ulnarabduktion"], 3, "In leichter Extension haben die Fingerbeuger die beste Länge."], ["Welche Sehne kann nach distaler Radiusfraktur reißen?", ["APL", "EPL", "FCR", "ECU"], 1, "Die EPL-Sehne läuft um das Tuberculum von Lister und kann dort nach der Fraktur reißen."]], "info": {}}, {"id": "w48-ana-osg", "titel": "Sprunggelenk und Fuß", "art": "ana", "min": 12, "abschnitte": [{"t": "1. Aufbau im Überblick", "b": [{"p": ["Das obere Sprunggelenk (OSG) verbindet die Malleolengabel aus Tibia und Fibula mit der Trochlea tali. Es ist im Wesentlichen ein Scharniergelenk für Dorsal- und Plantarflexion. Das untere Sprunggelenk (USG) zwischen Talus, Calcaneus und Naviculare macht Inversion und Eversion."]}, {"tab": [["Malleolengabel", "Tibia und Fibula umfassen den Talus. Der Außenknöchel reicht weiter nach distal als der Innenknöchel"], ["Trochlea tali", "Vorne breiter als hinten. In Dorsalextension sitzt der Talus fest in der Gabel, in Plantarflexion hat er mehr Spiel. Deshalb passiert das Supinationstrauma meist in Plantarflexion"], ["Syndesmose", "Bandverbindung zwischen distaler Tibia und Fibula, hält die Gabel zusammen"], ["Unteres Sprunggelenk", "Hintere Kammer (Talus–Calcaneus) und vordere Kammer (Talus–Calcaneus–Naviculare)"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-osg-knochen.webp", "t": "Rechtes oberes Sprunggelenk von vorne, Kapsel entfernt.", "c": "1 distale Tibia als Dach der Gabel, 2 Malleolus lateralis, 3 Trochlea tali, 4 Lig. tibiofibulare anterius (Syndesmose), 5 Malleolus medialis. Lateral liegt im Bild links."}]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."], "merk": "Plantarflexion plus Supination ist die instabilste Stellung des OSG, darum knicken wir meist so um."}]}, {"t": "2. Außenbänder und Syndesmose", "b": [{"tab": [["Lig. fibulotalare anterius (LFTA, ATFL)", "Schwächstes und am häufigsten verletztes Außenband. Spannt in Plantarflexion"], ["Lig. fibulocalcaneare (LFC, CFL)", "Zieht nach unten-hinten zum Calcaneus. Oft als zweites mitverletzt"], ["Lig. fibulotalare posterius (LFTP, PTFL)", "Kräftigstes Außenband, selten verletzt"], ["Syndesmose", "Lig. tibiofibulare anterius und posterius. Verletzt bei Außenrotation des Fußes (hohe Sprunggelenksverletzung), heilt langsamer"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-osg-aussen.webp", "t": "Rechtes Sprunggelenk von lateral.", "c": "1 Lig. fibulotalare anterius, 2 Lig. fibulocalcaneare, 3 Lig. fibulotalare posterius, 4 Lig. tibiofibulare anterius (Syndesmose), 5 Sehnen der Mm. fibulares. Die Ferse liegt im Bild links."}]}, {"merk": "Reihenfolge beim Supinationstrauma: erst LFTA, dann LFC, selten LFTP. Schmerz über der Syndesmose und beim Außenrotationstest spricht für eine hohe Verletzung."}]}, {"t": "3. Innenseite", "b": [{"tab": [["Lig. deltoideum", "Kräftiger Bandfächer vom Innenknöchel zu Talus, Calcaneus und Naviculare. Selten allein verletzt"], ["M. tibialis posterior", "Sehne hinter dem Innenknöchel zum Naviculare. Wichtigster dynamischer Halter des Längsgewölbes. Funktionsverlust führt zum erworbenen Plattfuß"], ["Tarsaltunnel", "Unter dem Retinaculum flexorum hinter dem Innenknöchel, mit N. tibialis, A. tibialis posterior und den langen Beugesehnen"], ["Pfannenband (Lig. calcaneonaviculare plantare)", "Trägt den Taluskopf von unten"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-osg-innen.webp", "t": "Rechtes Sprunggelenk von medial.", "c": "1 Lig. deltoideum, 2 Sehne des M. tibialis posterior, 3 Sustentaculum tali, 4 Tarsaltunnel mit N. tibialis und A. tibialis posterior, 5 Pfannenband. Die Ferse liegt im Bild rechts."}]}, {"merk": "Kann der Patient auf der betroffenen Seite nicht einbeinig auf die Zehen, an die Tibialis-posterior-Sehne denken."}]}, {"t": "4. Muskeln", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W48/ana-osg-wade.webp", "t": "Rechter Unterschenkel von hinten.", "c": "1 Caput mediale des M. gastrocnemius, 2 Caput laterale, 3 M. soleus, 4 Achillessehne mit ihrer schmalsten Stelle 2–6 cm über dem Ansatz, 5 Tuber calcanei. Medial liegt im Bild links."}]}, {"mus": [{"n": "M. gastrocnemius", "z": "1–2", "u": "Kondylen des Femur (zweigelenkig)", "a": "Über die Achillessehne am Tuber calcanei", "i": "N. tibialis (S1–S2)", "f": "Plantarflexion, vor allem bei gestrecktem Knie, beugt auch das Knie"}, {"n": "M. soleus", "z": "3", "u": "Fibulakopf und Hinterfläche von Tibia und Fibula (eingelenkig)", "a": "Über die Achillessehne am Tuber calcanei", "i": "N. tibialis (S1–S2)", "f": "Plantarflexion, auch bei gebeugtem Knie. Wichtig für Haltung und Venenpumpe"}, {"n": "M. tibialis anterior", "u": "Laterale Fläche der Tibia", "a": "Os cuneiforme mediale und Basis des 1. Mittelfußknochens", "i": "N. fibularis profundus (L4–L5)", "f": "Dorsalextension und Supination. Ausfall führt zum Steppergang"}, {"n": "M. tibialis posterior", "u": "Membrana interossea, Tibia und Fibula hinten", "a": "Naviculare und weitere Fußwurzelknochen", "i": "N. tibialis", "f": "Supination und Plantarflexion, hält das Längsgewölbe"}, {"n": "Mm. fibulares longus und brevis", "u": "Laterale Fibula", "a": "Longus: Cuneiforme mediale und Basis MT1 von plantar; Brevis: Basis MT5", "i": "N. fibularis superficialis", "f": "Pronation und Plantarflexion, schützen gegen das Umknicken nach außen"}]}, {"merk": "Wadenkraft prüfen: Gastrocnemius mit gestrecktem Knie, Soleus mit gebeugtem Knie."}]}, {"t": "5. Fuß und Gelenklinien", "b": [{"tab": [["Chopart-Gelenklinie", "Zwischen Talus und Naviculare sowie Calcaneus und Cuboid. Quere Gelenklinie mitten im Fuß"], ["Lisfranc-Gelenklinie", "Zwischen Fußwurzel und Mittelfußknochen. Verletzungen werden leicht übersehen"], ["Basis des 5. Mittelfußknochens", "Ansatz des Fibularis brevis. Typische Abrissfraktur beim Supinationstrauma, darum immer tasten"], ["Längsgewölbe", "Getragen von Knochenform, Plantarfaszie, Bändern und Muskeln (Tibialis posterior, Fibularis longus, kurze Fußmuskeln)"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-osg-fuss.webp", "t": "Rechtes Fußskelett von oben, Zehen oben.", "c": "1 Chopart-Gelenklinie (blau), 2 Lisfranc-Gelenklinie (orange), 3 Os naviculare, 4 Os cuboideum, 5 Basis des 5. Mittelfußknochens, 6 Taluskopf. Die Großzehe liegt im Bild links."}]}, {"merk": "Nach dem Umknicken die Ottawa-Regeln anwenden: Druckschmerz an Knöchelhinterkante, Basis MT5 oder Naviculare oder nicht 4 Schritte gehen können heißt röntgen."}]}, {"t": "6. Klinische Bezüge", "b": [{"l": ["Laterale Bandverletzung: häufigste Sportverletzung. Funktionelle Behandlung mit Orthese und Training, danach Gleichgewichtstraining gegen Rückfälle.", "Syndesmosenverletzung: Schmerz vorne zwischen Tibia und Fibula, positiver Squeeze- oder Außenrotationstest. Längere Ausfallzeit.", "Achillessehnen-Tendinopathie: meist im Mittelteil, 2–6 cm über dem Ansatz, wo die Durchblutung am schwächsten ist.", "Tibialis-posterior-Dysfunktion: zunehmender Plattfuß, Schmerz hinter dem Innenknöchel.", "Tarsaltunnelsyndrom: Brennen und Kribbeln an der Fußsohle, Engpass für den N. tibialis."]}, {"merk": "Nach Supinationstrauma immer auch die Basis des 5. Mittelfußknochens tasten."}]}], "quellen": ["Schünke M, Schulte E, Schumacher U. Prometheus LernAtlas Allgemeine Anatomie und Bewegungssystem", "Kapandji IA. Funktionelle Anatomie der Gelenke, Band 2", "Stiell IG et al. Ottawa ankle rules. JAMA 1993"], "fragen": [["Welches Außenband ist mit der 1 markiert?", ["Lig. fibulocalcaneare", "Lig. fibulotalare posterius", "Lig. tibiofibulare anterius", "Lig. fibulotalare anterius"], 3, "Die 1 ist das LFTA, das schwächste und am häufigsten verletzte Außenband.", "fortbildung/bilder/2026-W48/ana-osg-aussen.webp"], ["Warum knickt man meist in Plantarflexion um?", ["Die Trochlea tali ist hinten schmaler und hat in der Gabel mehr Spiel", "Die Bänder sind dann locker", "Die Muskeln sind dann ausgeschaltet", "Der Innenknöchel ist länger"], 0, "Die Trochlea ist vorne breiter. In Plantarflexion steht der schmale Teil in der Gabel."], ["Welcher Knöchel reicht weiter nach distal?", ["Der Außenknöchel", "Der Innenknöchel", "Beide gleich", "Das hängt vom Alter ab"], 0, "Der Außenknöchel reicht tiefer, deshalb ist Eversion knöchern begrenzt."], ["Was ist mit der 4 markiert?", ["Lig. tibiofibulare anterius (Syndesmose)", "Lig. fibulotalare anterius", "Malleolus medialis", "Trochlea tali"], 0, "Die Syndesmose verbindet Tibia und Fibula und hält die Gabel zusammen.", "fortbildung/bilder/2026-W48/ana-osg-knochen.webp"], ["Welche Sehne hält dynamisch vor allem das Längsgewölbe?", ["M. tibialis anterior", "M. fibularis brevis", "M. tibialis posterior", "Achillessehne"], 2, "Funktionsverlust der Tibialis-posterior-Sehne führt zum erworbenen Plattfuß."], ["Was verläuft im Tarsaltunnel?", ["N. fibularis superficialis", "N. suralis", "N. saphenus", "N. tibialis mit A. tibialis posterior"], 3, "Der Tarsaltunnel liegt hinter dem Innenknöchel unter dem Retinaculum flexorum."], ["Wie prüft man den M. soleus getrennt vom Gastrocnemius?", ["Mit gestrecktem Knie", "Mit gebeugtem Knie", "Im Einbeinstand mit Hüftbeugung", "Gar nicht"], 1, "Bei gebeugtem Knie ist der zweigelenkige Gastrocnemius angenähert, dann arbeitet vor allem der Soleus."], ["Wo ist die Achillessehne am schmalsten und am schwächsten durchblutet?", ["Direkt am Ansatz", "Etwa 2–6 cm über dem Ansatz", "Am Muskel-Sehnen-Übergang", "Am Tuber calcanei"], 1, "Dort entsteht meist die Tendinopathie des Mittelteils."], ["Was zeigt die 2?", ["Chopart-Gelenklinie", "Basis MT5", "Lisfranc-Gelenklinie", "Os naviculare"], 2, "Die orange Linie ist die Lisfranc-Gelenklinie zwischen Fußwurzel und Mittelfuß.", "fortbildung/bilder/2026-W48/ana-osg-fuss.webp"], ["Welcher Muskel setzt an der Basis des 5. Mittelfußknochens an?", ["M. fibularis longus", "M. tibialis anterior", "M. extensor digitorum longus", "M. fibularis brevis"], 3, "Der Zug des Fibularis brevis kann dort beim Umknicken einen Knochen abreißen."], ["Welcher Befund verlangt nach den Ottawa-Regeln ein Röntgen?", ["Schwellung vor dem Außenknöchel", "Bluterguss am Fußrücken", "Druckschmerz an der Basis des 5. Mittelfußknochens", "Schmerz beim Laufen nach 2 Tagen"], 2, "Druckschmerz an Knöchelhinterkante, Basis MT5 oder Naviculare oder nicht 4 Schritte gehen können."]], "info": {}}, {"id": "w48-ana-bws", "titel": "Brustwirbelsäule und Brustkorb", "art": "ana", "min": 11, "abschnitte": [{"t": "1. Aufbau im Überblick", "b": [{"p": ["Die BWS hat zwölf Wirbel, jeder trägt ein Rippenpaar. Zusammen mit Rippen und Sternum bildet sie den Brustkorb. Das macht sie steifer als HWS und LWS, schützt Herz und Lunge und gibt den Schulterblättern eine Gleitfläche."]}, {"tab": [["Wirbelkörper", "Herzförmig, mit Gelenkflächen für die Rippenköpfe"], ["Dornfortsätze", "Lang und steil nach unten gerichtet, liegen dachziegelartig übereinander. Der tastbare Dornfortsatz liegt deshalb tiefer als der zugehörige Wirbelkörper"], ["Facettengelenke", "Fast frontal gestellt. Das erlaubt Rotation und Seitneigung, die Rippen bremsen aber"], ["Kyphose", "Physiologisch etwa 20–40°, nimmt mit dem Alter zu"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-bws-wirbel.webp", "t": "Zwei Brustwirbel mit Rippe von links.", "c": "1 Rippenkopfgelenk am Wirbelkörper, 2 Kostotransversalgelenk, 3 langer, nach unten gerichteter Dornfortsatz, 4 frontal gestelltes Facettengelenk, 5 Foramen intervertebrale. Vorne liegt im Bild links."}]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."], "merk": "Jede Rippe hat zwei Gelenke mit der Wirbelsäule. Rippenblockaden fühlen sich deshalb oft wie BWS-Schmerz an, mit Ausstrahlung entlang der Rippe."}]}, {"t": "2. Brustkorb", "b": [{"tab": [["Echte Rippen (1–7)", "Direkt über eigenen Knorpel am Sternum"], ["Falsche Rippen (8–10)", "Über den gemeinsamen Rippenbogen mit dem Sternum verbunden"], ["Freie Rippen (11–12)", "Enden frei in der Bauchwand"], ["Angulus sterni", "Tastbare Kante zwischen Manubrium und Corpus, Höhe der 2. Rippe. Startpunkt zum Abzählen der Rippen"], ["Sternum", "Manubrium, Corpus und Proc. xiphoideus"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-bws-thorax.webp", "t": "Brustkorb von vorne.", "c": "1 Corpus sterni, 2 Angulus sterni auf Höhe der 2. Rippe, 3 echte Rippe (4. Rippe), 4 Rippenbogen aus den Rippen 8–10, 5 freie Rippen 11 und 12, 6 Proc. xiphoideus."}]}, {"merk": "Rippen zählen: am Angulus sterni die 2. Rippe finden und von dort nach unten weiterzählen."}]}, {"t": "3. Atembewegung", "b": [{"l": ["Obere Rippen bewegen sich wie ein Pumpenschwengel: Das Sternum geht beim Einatmen nach vorne oben, der Brustkorb wird tiefer von vorne nach hinten.", "Untere Rippen bewegen sich wie ein Eimerhenkel: Die seitlichen Teile heben sich nach außen, der Brustkorb wird breiter.", "Das Zwerchfell ist der wichtigste Einatemmuskel. Es senkt sich beim Einatmen und vergrößert den Brustraum nach unten.", "Atemhilfsmuskeln (Scaleni, Sternocleidomastoideus, Pectorales) arbeiten bei Belastung und Atemnot mit."]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-bws-atmung.webp", "t": "Schema der Rippenbewegung beim Einatmen.", "c": "1 Pumpenschwengelbewegung der oberen Rippen (Ansicht von der Seite), 2 Eimerhenkelbewegung der unteren Rippen (Ansicht von vorne), 3 Zwerchfell senkt sich. Gestrichelt die Ausatemstellung."}]}, {"merk": "Eine steife BWS schränkt die Atmung ein. Mobilisation der BWS und Rippen gehört deshalb auch zur Atemtherapie."}]}, {"t": "4. Muskeln", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W48/ana-bws-muskeln.webp", "t": "Oberer Rücken von hinten, rechts tiefe Schicht.", "c": "1 M. trapezius, mittlerer und aufsteigender Teil (linke Körperhälfte), 2 Mm. rhomboidei, 3 M. latissimus dorsi, 4 M. erector spinae thorakal, 5 Spina scapulae mit Acromion. Rechts ist der Trapezius entfernt."}]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-bws-zwerchfell.webp", "t": "Brustkorb von vorne-links eröffnet, Atemmuskeln.", "c": "1 Zwerchfell mit Centrum tendineum, 2 Mm. intercostales externi, 3 Mm. intercostales interni, 4 Gefäß-Nerven-Straße am Unterrand der Rippe, 5 Mm. scaleni."}]}, {"mus": [{"n": "M. trapezius pars ascendens", "z": "1", "u": "Dornfortsätze Th5–Th12", "a": "Spina scapulae medial", "i": "N. accessorius (XI)", "f": "Zieht das Schulterblatt nach unten und dreht es beim Armheben nach oben"}, {"n": "Mm. rhomboidei", "z": "2", "u": "Dornfortsätze C6–Th4", "a": "Margo medialis scapulae", "i": "N. dorsalis scapulae (C4–C5)", "f": "Ziehen das Schulterblatt zur Wirbelsäule und nach oben"}, {"n": "M. latissimus dorsi", "z": "3", "u": "Dornfortsätze Th7–L5, Fascia thoracolumbalis, Darmbeinkamm, untere Rippen", "a": "Crista tuberculi minoris humeri", "i": "N. thoracodorsalis (C6–C8)", "f": "Extension, Adduktion und Innenrotation im Schultergelenk, verbindet Arm und Becken"}, {"n": "M. erector spinae", "z": "4", "u": "Kreuzbein, Darmbeinkamm, Dornfortsätze und Querfortsätze", "a": "Rippen, Wirbel, Hinterhaupt", "i": "Rr. dorsales der Spinalnerven", "f": "Streckt und neigt die Wirbelsäule, hält die Aufrichtung"}, {"n": "Diaphragma", "z": "1", "b": "ana-bws-zwerchfell.webp", "u": "Proc. xiphoideus, untere Rippen, Lendenwirbel (Crura)", "a": "Centrum tendineum", "i": "N. phrenicus (C3–C5)", "f": "Wichtigster Einatemmuskel"}]}, {"merk": "Der N. phrenicus kommt aus C3–C5. Hohe Halsmarkverletzungen können deshalb die Zwerchfellatmung lähmen."}]}, {"t": "5. Biomechanik, Nerven und Gefäße", "b": [{"l": ["Rotation ist in der BWS größer als in der LWS, etwa 30–35° zu jeder Seite. Flexion und Extension sind durch Rippen und Dornfortsätze begrenzt.", "Für volles Armheben braucht es Extension der BWS. Bei starker Kyphose fehlt Elevation in der Schulter.", "Die Interkostalnerven verlaufen mit Arterie und Vene am Unterrand der Rippe. Punktionen setzt man deshalb am Oberrand der unteren Rippe.", "Dermatome am Rumpf: Th4 etwa Höhe der Brustwarzen, Th10 Höhe des Bauchnabels.", "Der Spinalkanal ist in der BWS eng. Raumforderungen machen hier früher Rückenmarkszeichen."]}, {"merk": "Th4 Brustwarze, Th10 Bauchnabel. Gürtelförmiger Schmerz entlang einer Rippe passt zu einem Interkostalnerv."}]}, {"t": "6. Klinische Bezüge", "b": [{"l": ["Osteoporotische Wirbelkörperfraktur: am häufigsten am thorakolumbalen Übergang. Plötzlicher Rückenschmerz bei älteren Menschen, oft ohne starkes Trauma.", "Morbus Scheuermann: Wachstumsstörung der Wirbelkörper mit fixierter Kyphose bei Jugendlichen.", "Rippenfraktur und Prellung: Schmerz beim Atmen und Husten. Atemtherapie gegen Pneumonie.", "Thorakaler Schmerz kann aus Herz, Lunge, Aorta oder Bauchorganen kommen. Bei Schmerz ohne Bewegungsbezug, Atemnot oder Kaltschweiß sofort ärztlich.", "Axiale Spondyloarthritis: eingeschränkte Thoraxexkursion als Spätzeichen."]}, {"merk": "Brustschmerz ohne Bezug zu Bewegung oder Haltung ist erst mal kein Fall für die Physiotherapie."}]}], "quellen": ["Schünke M, Schulte E, Schumacher U. Prometheus LernAtlas Allgemeine Anatomie und Bewegungssystem", "Kapandji IA. Funktionelle Anatomie der Gelenke, Band 3"], "fragen": [["Welches Gelenk ist mit der 2 markiert?", ["Rippenkopfgelenk", "Facettengelenk", "Kostotransversalgelenk", "Sternokostalgelenk"], 2, "Das Tuberculum der Rippe gelenkt mit dem Querfortsatz, das Kostotransversalgelenk.", "fortbildung/bilder/2026-W48/ana-bws-wirbel.webp"], ["Warum liegt der tastbare Dornfortsatz in der BWS tiefer als sein Wirbelkörper?", ["Die BWS ist lordotisch", "Die Wirbelkörper sind klein", "Die Dornfortsätze sind lang und steil nach unten gerichtet", "Die Rippen verdecken sie"], 2, "Die Dornfortsätze liegen dachziegelartig übereinander."], ["Welche Rippen sind echte Rippen?", ["1–5", "8–10", "11–12", "1–7"], 3, "Rippen 1–7 haben einen eigenen Knorpel bis zum Sternum."], ["Was ist mit der 2 markiert?", ["Proc. xiphoideus", "Manubrium-Klavikula-Gelenk", "Rippenbogen", "Angulus sterni auf Höhe der 2. Rippe"], 3, "Am Angulus sterni setzt die 2. Rippe an, von dort zählt man die Rippen.", "fortbildung/bilder/2026-W48/ana-bws-thorax.webp"], ["Wie bewegen sich die unteren Rippen beim Einatmen?", ["Wie ein Eimerhenkel nach außen oben", "Wie ein Pumpenschwengel nach vorne", "Gar nicht", "Nach unten"], 0, "Die seitlichen Teile heben sich, der Brustkorb wird breiter."], ["Was ist der wichtigste Einatemmuskel?", ["M. sternocleidomastoideus", "Mm. intercostales interni", "Diaphragma", "M. rectus abdominis"], 2, "Das Zwerchfell senkt sich und vergrößert den Brustraum."], ["Aus welchen Segmenten kommt der N. phrenicus?", ["C1–C2", "C3–C5", "C6–C8", "Th1–Th2"], 1, "C3, C4 und C5, deshalb sind hohe Halsmarkverletzungen für die Atmung gefährlich."], ["Wo verläuft die Gefäß-Nerven-Straße eines Interkostalraums?", ["Am Unterrand der Rippe", "Am Oberrand der Rippe", "Mitten im Interkostalraum", "Am Sternum"], 0, "Nerv, Arterie und Vene liegen am Unterrand der Rippe."], ["Welcher Muskel ist mit der 2 markiert?", ["Mm. rhomboidei", "M. trapezius pars ascendens", "M. latissimus dorsi", "M. levator scapulae"], 0, "Die Rhomboidei liegen zwischen Wirbelsäule und medialem Schulterblattrand unter dem Trapezius.", "fortbildung/bilder/2026-W48/ana-bws-muskeln.webp"], ["Welches Dermatom liegt etwa auf Höhe des Bauchnabels?", ["Th4", "Th7", "L1", "Th10"], 3, "Th10 am Nabel, Th4 an den Brustwarzen."], ["Wo treten osteoporotische Wirbelkörperfrakturen am häufigsten auf?", ["Obere HWS", "Thorakolumbaler Übergang", "Kreuzbein", "Th1–Th2"], 1, "Am Übergang von BWS zu LWS ist die Last am größten."]], "info": {}}, {"id": "w48-ana-isg", "titel": "Becken und ISG", "art": "ana", "min": 11, "abschnitte": [{"t": "1. Aufbau im Überblick", "b": [{"p": ["Der Beckenring besteht aus den beiden Hüftbeinen und dem Kreuzbein. Hinten verbinden ihn die beiden Iliosakralgelenke (ISG), vorne die Symphyse. Er überträgt das Gewicht des Rumpfes auf die Beine."]}, {"tab": [["ISG", "Ohrförmige Gelenkflächen von Kreuzbein und Darmbein, unregelmäßig verzahnt. Echtes Gelenk mit Kapsel, aber nur wenige Millimeter und Grad Bewegung"], ["Symphyse", "Faserknorpelige Verbindung der Schambeine. Lockert sich in der Schwangerschaft"], ["SIAS und SIPS", "Tastpunkte vorne und hinten am Becken. Die Grübchen über den SIPS liegen etwa auf Höhe S2"], ["Acetabulum", "Hüftpfanne aus Darm-, Sitz- und Schambein"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-isg-becken.webp", "t": "Becken von vorne.", "c": "1 Iliosakralgelenk, 2 Symphyse, 3 Spina iliaca anterior superior (SIAS), 4 Os sacrum, 5 Acetabulum, 6 Crista iliaca."}]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."], "merk": "Das ISG bewegt sich nur wenig, wenige Millimeter. Was Tests als Blockade beschreiben, ist meist eine Schmerzprovokation, kein messbarer Bewegungsverlust."}]}, {"t": "2. Bänder", "b": [{"tab": [["Ligg. sacroiliaca posteriora", "Kräftige Bänder hinten über dem ISG. Das lange dorsale Band ist unter der SIPS tastbar und oft druckschmerzhaft"], ["Lig. sacrotuberale", "Vom Kreuzbein zum Tuber ischiadicum. Verbunden mit dem langen Kopf des Biceps femoris, spannt bei Nutation"], ["Lig. sacrospinale", "Vom Kreuzbein zur Spina ischiadica. Teilt das Foramen ischiadicum majus und minus"], ["Foramen ischiadicum majus", "Durchtritt für N. ischiadicus, Piriformis und Gefäße"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-isg-baender.webp", "t": "Becken von hinten.", "c": "1 langes dorsales sakroiliakales Band, 2 Lig. sacrotuberale, 3 Lig. sacrospinale, 4 Foramen ischiadicum majus mit N. ischiadicus, 5 Crista iliaca. Ihr hinteres Ende ist die SIPS, direkt seitlich vom Kreuzbein."}]}, {"merk": "Druckschmerz direkt unter der SIPS über dem langen dorsalen Band passt gut zu ISG-Schmerz, vor allem in der Schwangerschaft."}]}, {"t": "3. Bewegung: Nutation und Kontranutation", "b": [{"l": ["Nutation: Die Kreuzbeinbasis kippt nach vorne unten, die Steißbeinspitze nach hinten oben. Das spannt das Lig. sacrotuberale und schließt das ISG, die Position ist stabil (Formschluss plus Kraftschluss).", "Kontranutation: umgekehrt, etwa im Liegen mit gestreckten Beinen. Die Bänder sind lockerer, das Gelenk weniger gesichert.", "Das Bewegungsausmaß liegt bei etwa 1–4° Rotation und wenigen Millimetern Verschiebung.", "Stabil wird das ISG durch die Form der Gelenkflächen (Formschluss) und durch Muskeln, Faszien und Bänder (Kraftschluss)."]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-isg-nutation.webp", "t": "Rechte Beckenhälfte mit Kreuzbein von der Seite.", "c": "1 Nutation, die Basis kippt nach vorne unten, 2 Lig. sacrotuberale spannt sich, 3 Gelenkfläche des ISG. Gestrichelt die Neutralstellung, vorne liegt im Bild rechts."}]}, {"merk": "Nutation heißt stabil. Gürtel und aktivierte Muskeln wirken in dieselbe Richtung: Sie drücken die Gelenkflächen zusammen."}]}, {"t": "4. Muskeln und Beckenboden", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W48/ana-isg-piriformis.webp", "t": "Rechte Gesäßregion von hinten, Gluteus maximus entfernt.", "c": "1 M. piriformis, 2 N. ischiadicus unterhalb des Piriformis, 3 M. gluteus medius, 4 Lig. sacrotuberale, 5 Trochanter major. Das Kreuzbein liegt im Bild links."}]}, {"fig": [{"src": "fortbildung/bilder/2026-W48/ana-isg-schlinge.webp", "t": "Rücken von hinten, hintere schräge Muskelschlinge.", "c": "1 rechter M. gluteus maximus, 2 Fascia thoracolumbalis, 3 linker M. latissimus dorsi, 4 langer Kopf des M. biceps femoris mit Übergang ins Lig. sacrotuberale, 5 Iliosakralgelenk."}]}, {"mus": [{"n": "M. gluteus maximus", "z": "1", "b": "ana-isg-schlinge.webp", "u": "Darmbein hinten, Kreuzbein, Steißbein, Lig. sacrotuberale, Fascia thoracolumbalis", "a": "Tuberositas glutea und Tractus iliotibialis", "i": "N. gluteus inferior (L5–S2)", "f": "Hüftextension und Außenrotation. Spannt über die Faszie das ISG"}, {"n": "M. latissimus dorsi", "z": "3", "b": "ana-isg-schlinge.webp", "u": "Fascia thoracolumbalis, Dornfortsätze, Darmbeinkamm", "a": "Crista tuberculi minoris humeri", "i": "N. thoracodorsalis", "f": "Bildet mit dem gegenseitigen Gluteus maximus die hintere schräge Schlinge"}, {"n": "M. levator ani", "u": "Schambein und Sehnenbogen über dem Obturator internus", "a": "Steißbein und Lig. anococcygeum", "i": "Äste aus S3–S4", "f": "Trägt die Beckenorgane, unterstützt Kontinenz und Rumpfstabilität"}, {"n": "M. piriformis", "z": "1", "b": "ana-isg-piriformis.webp", "u": "Vorderfläche des Kreuzbeins", "a": "Trochanter major", "i": "Plexus sacralis (S1–S2)", "f": "Außenrotation, zieht durch das Foramen ischiadicum majus. Nahe Beziehung zum N. ischiadicus"}, {"n": "M. transversus abdominis", "u": "Untere Rippen, Fascia thoracolumbalis, Darmbeinkamm, Leistenband", "a": "Rektusscheide", "i": "Nn. intercostales Th7–Th12, L1", "f": "Erhöht den Bauchinnendruck und spannt die Fascia thoracolumbalis"}]}, {"merk": "Gluteus maximus und gegenseitiger Latissimus spannen über die Fascia thoracolumbalis gemeinsam das ISG. Training in diagonalen Mustern nutzt das."}]}, {"t": "5. Nerven und Schmerzmuster", "b": [{"l": ["Das ISG wird vor allem aus den Rr. dorsales L5–S3 versorgt.", "ISG-Schmerz liegt typisch unter dem Gürtel, um die SIPS und ins Gesäß, selten bis unter das Knie.", "Der N. ischiadicus verlässt das Becken durch das Foramen ischiadicum majus, meist unter dem Piriformis.", "Laslett 2005: Sind 2 von 4 Provokationstests (Distraktion, Thigh Thrust, Kompression, Sacral Thrust) positiv oder 3 von 6 mit Gaenslen beidseits, ist das ISG als Schmerzquelle wahrscheinlich. Am aussagekräftigsten sind Distraktion und Thigh Thrust.", "Einzelne Mobilitätstests (Vorlauf, Spine-Test) sind kaum zuverlässig."]}, {"merk": "ISG-Schmerz zeigt man meist mit einem Finger auf die SIPS (Fortin-Finger-Test). Strahlt es bis in den Fuß, eher an eine Wurzel denken."}]}, {"t": "6. Klinische Bezüge", "b": [{"l": ["Beckengürtelschmerz in der Schwangerschaft: häufig, Schmerz um ISG und Symphyse. Aktiv bleiben, gezielte Übungen, Beckengurt kann helfen.", "Axiale Spondyloarthritis: Entzündung oft zuerst im ISG. Junge Patienten mit nächtlichem Kreuzschmerz und Morgensteifigkeit über 30 Minuten ärztlich abklären lassen.", "Beckenringfraktur: nach Hochrasanztrauma oder bei Osteoporose als Insuffizienzfraktur des Kreuzbeins.", "Beckenboden: Belastungsinkontinenz nach Geburt, Training mit Anleitung ist erste Wahl.", "Piriformissyndrom: Gesäßschmerz mit Ausstrahlung, Abgrenzung zur Radikulopathie über die Neurologie."]}, {"merk": "Kreuzschmerz bei Jüngeren mit Morgensteifigkeit, nächtlichem Schmerz und Besserung durch Bewegung: an eine axiale Spondyloarthritis denken."}]}], "quellen": ["Schünke M, Schulte E, Schumacher U. Prometheus LernAtlas Allgemeine Anatomie und Bewegungssystem", "Vleeming A et al. The sacroiliac joint: an overview of its anatomy, function and potential clinical implications. J Anat 2012", "Laslett M et al. Diagnosis of sacroiliac joint pain: validity of individual provocation tests and composites of tests. Man Ther 2005"], "fragen": [["Was ist am Becken mit der 1 markiert?", ["Symphyse", "Acetabulum", "Iliosakralgelenk", "SIAS"], 2, "Das ISG verbindet Kreuzbein und Darmbein.", "fortbildung/bilder/2026-W48/ana-isg-becken.webp"], ["Wie groß ist die Bewegung im ISG etwa?", ["20–30° Rotation", "Etwa 1–4° Rotation und wenige Millimeter", "Keine, es ist verwachsen", "So viel wie im Hüftgelenk"], 1, "Das ISG ist ein echtes Gelenk, bewegt sich aber nur sehr wenig."], ["Welches Band ist mit der 2 markiert?", ["Lig. sacrospinale", "Langes dorsales Band", "Lig. iliolumbale", "Lig. sacrotuberale"], 3, "Das Lig. sacrotuberale zieht vom Kreuzbein zum Sitzbeinhöcker.", "fortbildung/bilder/2026-W48/ana-isg-baender.webp"], ["Was passiert bei der Nutation?", ["Die Kreuzbeinbasis kippt nach vorne unten, das ISG wird stabiler", "Die Kreuzbeinbasis kippt nach hinten", "Die Symphyse öffnet sich weit", "Das Steißbein kippt nach vorne"], 0, "Nutation spannt das Lig. sacrotuberale und schließt das Gelenk."], ["Welcher Muskel ist über das Lig. sacrotuberale mit dem ISG verbunden?", ["Langer Kopf des M. biceps femoris", "M. rectus femoris", "M. sartorius", "M. gracilis"], 0, "Der lange Bizepskopf geht teilweise ins Lig. sacrotuberale über."], ["Welche Muskeln bilden die hintere schräge Schlinge?", ["Beide Psoas", "Rectus abdominis und Piriformis", "Gluteus medius und Adduktoren", "Rechter Gluteus maximus und linker Latissimus dorsi"], 3, "Über die Fascia thoracolumbalis spannen sie diagonal das ISG."], ["Welcher Muskel ist in der Gesäßregion mit der 1 markiert?", ["M. gluteus medius", "M. obturatorius internus", "M. piriformis", "M. quadratus femoris"], 2, "Der Piriformis zieht vom Kreuzbein zum Trochanter major. Der N. ischiadicus tritt meist unter ihm aus.", "fortbildung/bilder/2026-W48/ana-isg-piriformis.webp"], ["Ab wann ist das ISG nach Laslett 2005 als Schmerzquelle wahrscheinlich?", ["Ab 2 von 4 Provokationstests (Distraktion, Thigh Thrust, Kompression, Sacral Thrust)", "Ab 1 positiven Mobilitätstest", "Erst wenn alle 6 Tests positiv sind", "Wenn der Vorlauftest positiv ist"], 0, "2 von 4 der genannten Provokationstests oder 3 von 6 mit Gaenslen beidseits. Mobilitätstests sind kaum zuverlässig."], ["Durch welche Öffnung verlässt der N. ischiadicus das Becken?", ["Foramen obturatum", "Foramen ischiadicum minus", "Hiatus sacralis", "Foramen ischiadicum majus"], 3, "Meist unter dem Piriformis durch das Foramen ischiadicum majus."], ["Woran zeigt der Patient beim Fortin-Finger-Test typischerweise?", ["Auf die Leiste", "Auf den Trochanter", "Mit einem Finger auf die SIPS", "Auf das Steißbein"], 2, "Ein Finger direkt an oder unter der SIPS spricht für ISG-Schmerz."], ["Welches Muster spricht eher für eine axiale Spondyloarthritis?", ["Schmerz nach langem Stehen, besser in Ruhe", "Junger Patient, nächtlicher Kreuzschmerz, Morgensteifigkeit über 30 Minuten, besser durch Bewegung", "Schmerz nur beim Bücken", "Ausstrahlung bis in den Fuß mit Taubheit"], 1, "Entzündlicher Rückenschmerz bessert sich durch Bewegung und gehört ärztlich abgeklärt."]], "info": {}}]});
